INSERT INTO `acticonservations` (`id`, `title`, `intro`, `file_text`, `date`, `slug`, `image_desktop`, `status`, `file_pdf`, `count_view`, `meta_title`, `meta_description`, `meta_keyword`, `ip_address`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'ลงพื้นที่เเพื่อจัดทำฐานข้อมูล', 'ลงพื้นที่ ณ วัดโพธิ์งาม ต.โพธิ์เก้าต้น อ.เมือง จ.ลพบุรี และ วัดหลวงสุวรรณาราม ต.ตะลุง อ.เมือง จ.ลพบุรี เพื่อเก็บข้อมูลโบราณสถานและข้อมูลทรัพยากรธรรมชาติที่น่าสนใจของท้องถิ่น', 'acticonservation-1727986336835722.text', '2022-03-23', NULL, '1727991450541317.jpg', NULL, NULL, 286, NULL, NULL, NULL, '110.77.184.57', '2022-03-21 18:03:08', '2024-10-21 22:28:32', '0'),
(2, 'ประชุมวิชาการสำนักงานนโยบายและแผนทรัพยากรธรรมชาติและสิ่งแวดล้อมประจำปี พ.ศ.2564', 'ประชุมวิชาการสำนักงานนโยบายและแผนทรัพยากรธรรมชาติและสิ่งแวดล้อมประจำปี พ.ศ.2564', 'acticonservation-1727991404601594.text', '2022-04-02', NULL, '1727991404633012.jpg', NULL, '1728069325665312.pdf', 232, 'ประชุมวิชาการสำนักงานนโยบายและแผนทรัพยากรธรรมชาติและสิ่งแวดล้อมประจำปี พ.ศ.2564', 'ประชุมวิชาการสำนักงานนโยบายและแผนทรัพยากรธรรมชาติและสิ่งแวดล้อมประจำปี พ.ศ.2564', 'ประชุมวิชาการสำนักงานนโยบายและแผนทรัพยากรธรรมชาติและสิ่งแวดล้อมประจำปี พ.ศ.2564', '2001:44c8:4101:feda:b5e0:37e8:c4f6:ebc5', '2022-03-21 19:23:41', '2024-10-09 16:57:37', '0'),
(3, 'การประชุมประจำปีภาคีอนุรักษ์สิ่งแวดล้อมธรรมชาติและศิลปกรรมกลุ่มจังหวัด พ.ศ. 2565', 'การประชุมประจำปีภาคีอนุรักษ์สิ่งแวดล้อมธรรมชาติและศิลปกรรมกลุ่มจังหวัด พ.ศ. 2565', 'acticonservation-1730591974723436.text', '2022-04-20', NULL, '1730591974732279.jpg', NULL, NULL, 298, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-19 12:18:38', '2024-10-19 11:25:31', '0');
