INSERT INTO `activitys` (`id`, `activity_title`, `activity_intro`, `activity_file_text`, `activity_date`, `activity_year`, `activity_slug`, `activity_image_desktop`, `activity_status`, `file_pdf`, `count_view`, `activity_meta_title`, `activity_meta_description`, `activity_meta_keyword`, `ip_address`, `created_at`, `updated_at`, `deleted_at`) VALUES
(4, 'โครงการอบรมมัคคุเทศก์ทางวัฒนธรรม  ณ วัดอัมพวัน ตำบลบางขันหมาก อำเภอเมือง จังหวัดลพบุรี', 'โครงการอบรมมัคคุเทศก์ทางวัฒนธรรม  ณ วัดอัมพวัน ตำบลบางขันหมาก อำเภอเมือง จังหวัดลพบุรี', 'acti-1730518319276593.text', '2022-04-19', NULL, NULL, '1730518319282541.jpg', NULL, NULL, 85, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 16:47:55', '2024-10-16 15:41:08', '0'),
(5, 'โครงการเสวนาวิชาการด้านศิลปะและวัฒนธรรม', 'โครงการเสวนาวิชาการด้านศิลปะและวัฒนธรรม', 'acti-1730519117930586.text', '2022-04-19', NULL, NULL, '1730519117939051.jpg', NULL, NULL, 84, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:00:36', '2024-10-14 08:10:15', '0'),
(6, 'โครงการส่งเสริมการบูรณาการองค์ความรู้ด้านศิลปวัฒนธรรมสิ่งแวดล้อมภูมิปัญญาท้องถิ่', 'โครงการส่งเสริมการบูรณาการองค์ความรู้ด้านศิลปวัฒนธรรมสิ่งแวดล้อมภูมิปัญญาท้องถิ่', 'acti-1730519827020240.text', '2022-04-19', NULL, NULL, '1730519827028944.jpg', NULL, NULL, 91, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:11:53', '2024-10-21 10:01:23', '0'),
(7, 'พิธีพลีกรรมตักน้ำจากแหล่งน้ำศักดิ์สิทธิ์ เพื่อนำไปประกอบพิธีเสกน้ำอภิเษกในการพระราชพิธีพระบรมราชาภิเษก', 'พิธีพลีกรรมตักน้ำจากแหล่งน้ำศักดิ์สิทธิ์ เพื่อนำไปประกอบพิธีเสกน้ำอภิเษกในการพระราชพิธีพระบรมราชาภิเษก', 'acti-1730519925304704.text', '2022-04-19', NULL, NULL, '1730519925313508.jpg', NULL, NULL, 93, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:13:26', '2024-10-12 10:47:20', '0'),
(8, 'โครงการสร้างสรรค์ศิลปะเพื่อสังคม การอบรมเชิงปฏิบัติการ “แนวทางการสร้างสรรค์ผลงานสำหรับครูศิลปะ”', 'โครงการสร้างสรรค์ศิลปะเพื่อสังคม การอบรมเชิงปฏิบัติการ “แนวทางการสร้างสรรค์ผลงานสำหรับครูศิลปะ”', 'acti-1730520005538957.text', '2022-04-19', NULL, NULL, '1730520005547556.jpg', NULL, NULL, 94, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:14:43', '2024-10-12 13:25:02', '0'),
(9, 'โครงการประสานงานเครือข่ายศิลปะและวัฒนธรรมในสถาบันอุดมศึกษา กิจกรรมลานวิถีชีวิตตลาดน้ำ ตำรับอาหารลูกหลานพระศรีอาริย์ งานประเพณีแห่พระศรีอาริยเมตไตรย์', 'โครงการประสานงานเครือข่ายศิลปะและวัฒนธรรมในสถาบันอุดมศึกษา กิจกรรมลานวิถีชีวิตตลาดน้ำ ตำรับอาหารลูกหลานพระศรีอาริย์ งานประเพณีแห่พระศรีอาริยเมตไตรย์', 'acti-1730520066093912.text', '2022-04-19', NULL, NULL, '1730520066101831.jpg', NULL, NULL, 90, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:15:41', '2024-10-25 09:21:44', '0'),
(10, 'ประเพณีชักพระศรีอริยเมตไตรย วัดไลย์ จ.ลพบุรี  “งานประเพณีชักพระศรีอริยเมตไตรย” วัดไลย์ ตำบลเขาสมอคอน อำเภอท่าวุ้ง', 'ประเพณีชักพระศรีอริยเมตไตรย วัดไลย์ จ.ลพบุรี \r\n“งานประเพณีชักพระศรีอริยเมตไตรย” วัดไลย์ ตำบลเขาสมอคอน อำเภอท่าวุ้ง', 'acti-1730520205150850.text', '2022-04-19', NULL, NULL, '1730520205159505.jpg', NULL, NULL, 203, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:17:53', '2024-10-27 01:40:21', '0'),
(11, 'โครงการท่องเที่ยวทางวัฒนธรรมและปลูกฝังจิตอาสา “รับฟังบรรยายเรื่องประวัติศาสตร์เมืองกาญจนบุรีและชมพิพิธภัณฑ์ หอวัฒนธรรมเพื่อศึกษาประวัติศาสตร์ความเป็นมา”', 'โครงการท่องเที่ยวทางวัฒนธรรมและปลูกฝังจิตอาสา “รับฟังบรรยายเรื่องประวัติศาสตร์เมืองกาญจนบุรีและชมพิพิธภัณฑ์ หอวัฒนธรรมเพื่อศึกษาประวัติศาสตร์ความเป็นมา”', 'acti-1730520287474947.text', '2022-04-19', NULL, NULL, '1730520287483061.jpg', NULL, NULL, 136, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:19:12', '2024-10-16 19:55:26', '0'),
(12, 'โครงการเฉลิมพระเกียรติเนื่องในโอกาส มหามงคลพระราชพิธีบรมราชาภิเษก "แข่งขันจัดนิทรรศการประกวดผลงานการจัดการศึกษาตามพระราโชบายด้านการศึกษา', 'โครงการเฉลิมพระเกียรติเนื่องในโอกาส มหามงคลพระราชพิธีบรมราชาภิเษก "แข่งขันจัดนิทรรศการประกวดผลงานการจัดการศึกษาตามพระราโชบายด้านการศึกษา', 'acti-1730520475755540.text', '2022-04-19', NULL, NULL, '1730520475762443.jpg', NULL, NULL, 85, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:22:11', '2024-10-20 09:09:29', '0'),
(13, 'ลงพื้นที่เก็บข้อมูลทางวัฒนธรรมของชุมชนยวนในจังหวัดลพบุรี ณ วัดหนองกระเบียน อำเภอบ้านหมี่ จังหวัดลพบุรี', 'ลงพื้นที่เก็บข้อมูลทางวัฒนธรรมของชุมชนยวนในจังหวัดลพบุรี ณ วัดหนองกระเบียน อำเภอบ้านหมี่ จังหวัดลพบุรี', 'acti-1730520533557483.text', '2022-04-19', NULL, NULL, '1730520533563045.jpg', NULL, NULL, 86, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:23:06', '2024-10-21 10:06:47', '0'),
(14, 'โครงการพัฒนาความรู้บุคลากรเพื่อสนับสนุนงานด้านศิลปะวัฒนธรรม “ส่งเสริมทักษะการเตรียมสถานที่สำหรับอบรมสัมมนาและการผูกผ้าสำหรับตกแต่งนิทรรศการ” เพื่อส่งเสริมให้บุคลากรมีทักษะในการจัดเตรียมสถานที่อบรมประชุมสัมมนาเป็นการสร้างภาพลักษณ์ ที่ดีของมหาวิทยาลัย', 'โครงการพัฒนาความรู้บุคลากรเพื่อสนับสนุนงานด้านศิลปะวัฒนธรรม “ส่งเสริมทักษะการเตรียมสถานที่สำหรับอบรมสัมมนาและการผูกผ้าสำหรับตกแต่งนิทรรศการ” เพื่อส่งเสริมให้บุคลากรมีทักษะในการจัดเตรียมสถานที่อบรมประชุมสัมมนาเป็นการสร้างภาพลักษณ์ ที่ดีของมหาวิทยาลัย', 'acti-1730520644508619.text', '2022-04-19', NULL, NULL, '1730520644514155.jpg', NULL, NULL, 88, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:24:52', '2024-10-20 01:59:04', '0'),
(15, 'การอบรมเชิงปฏิบัติการแนวทางการสร้างสรรค์ผลงานสำหรับครูศิลปะ (การระบายสีน้ำ)', 'การอบรมเชิงปฏิบัติการแนวทางการสร้างสรรค์ผลงานสำหรับครูศิลปะ (การระบายสีน้ำ)', 'acti-1730520731973761.text', '2022-04-19', NULL, NULL, '1730520731981687.jpg', NULL, NULL, 80, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:26:16', '2024-10-20 08:51:29', '0'),
(16, 'ร่วมถวายพระพร เนื่องในโอกาสวันเฉลิมพระชนมพรรษาพระบาทสมเด็จพระปรเมนทรรามาธิบดีศรีสินทรมหาวชิราลงกรณฯ พระวชิรเกล้าเจ้าอยู่หัว และร่วมชมนิทรรศการเฉลิมพระเกียรติ', 'ร่วมถวายพระพร เนื่องในโอกาสวันเฉลิมพระชนมพรรษาพระบาทสมเด็จพระปรเมนทรรามาธิบดีศรีสินทรมหาวชิราลงกรณฯ พระวชิรเกล้าเจ้าอยู่หัว และร่วมชมนิทรรศการเฉลิมพระเกียรติ', 'acti-1730520865141519.text', '2022-04-19', NULL, NULL, '1730520865150301.jpg', NULL, NULL, 82, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:28:23', '2024-10-21 05:31:46', '0'),
(17, 'ถวายพระพรชัยมงคล สมเด็จพระนางเจ้าสิริกิติ์พระบรมราชินีนาถ พระบรมราชชนนีพันปีหลวง เนื่องในโอกาสวันเฉลิมพระชนมพรรษา ๑๒ สิงหาคม ๒๕๖๔', 'ถวายพระพรชัยมงคล สมเด็จพระนางเจ้าสิริกิติ์พระบรมราชินีนาถ พระบรมราชชนนีพันปีหลวง เนื่องในโอกาสวันเฉลิมพระชนมพรรษา ๑๒ สิงหาคม ๒๕๖๔', 'acti-1730520922430544.text', '2022-04-19', NULL, NULL, '1730520922438561.jpg', NULL, NULL, 69, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:29:17', '2024-10-20 08:33:30', '0'),
(18, 'กิจกรรมน้อมรำลึกในพระมหากรุณาธิคุณ เนื่องในวันคล้ายวันสวรรคตพระบาทสมเด็จพระบรมชนกาธิเบศร มหาภูมิพลอดุลยเดชมหาราช บรมนาถบพิตร (๑๓ ตุลาคม)', 'กิจกรรมน้อมรำลึกในพระมหากรุณาธิคุณ เนื่องในวันคล้ายวันสวรรคตพระบาทสมเด็จพระบรมชนกาธิเบศร มหาภูมิพลอดุลยเดชมหาราช บรมนาถบพิตร (๑๓ ตุลาคม)', 'acti-1730520986624946.text', '2022-04-19', NULL, NULL, '1730520986630449.jpg', NULL, NULL, 100, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:30:18', '2024-10-26 15:45:02', '0'),
(19, 'พิธีวางพวงมาลาถวายราชสักการะเบื้องหน้าพระบรมฉายาลักษณ์ พระบาทสมเด็จพระบรมชนกาธิเบศร มหาภูมิพลอดุลยเดชมหาราช บรมนาถบพิตร เนื่องในวันคล้ายวันสวรรคต วันที่ 13 ตุลาคม 2564', 'พิธีวางพวงมาลาถวายราชสักการะเบื้องหน้าพระบรมฉายาลักษณ์ พระบาทสมเด็จพระบรมชนกาธิเบศร มหาภูมิพลอดุลยเดชมหาราช บรมนาถบพิตร เนื่องในวันคล้ายวันสวรรคต วันที่ 13 ตุลาคม 2564', 'acti-1730521074793911.text', '2022-04-19', NULL, NULL, '1730521074802154.jpg', NULL, NULL, 103, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:31:43', '2024-10-08 00:41:51', '0'),
(20, 'โครงการสืบสานประเพณีลอยกระทง ณ ลานวัฒนเทพ มหาวิทยาลัยราชภัฏเทพสตรี', 'โครงการสืบสานประเพณีลอยกระทง ณ ลานวัฒนเทพ มหาวิทยาลัยราชภัฏเทพสตรี', 'acti-1730521127882750.text', '2022-04-19', NULL, NULL, '1730521127890603.jpg', NULL, NULL, 84, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:32:33', '2024-10-26 15:42:02', '0'),
(21, 'ตักบาตรดอกไม้บูชาพระอุปคุตและร่วมเป็นเจ้าภาพในการสวดบังสกุลให้กับผู้ที่ล่วงลับและร่วมกิจกรรมลอยกระทง ณ วัดอัมพวัน  ต.บางขันหมาก อ.เมือง จ.ลพบุรี', 'ตักบาตรดอกไม้บูชาพระอุปคุตและร่วมเป็นเจ้าภาพในการสวดบังสกุลให้กับผู้ที่ล่วงลับและร่วมกิจกรรมลอยกระทง ณ วัดอัมพวัน  ต.บางขันหมาก อ.เมือง จ.ลพบุรี', 'acti-1730521185189719.text', '2022-04-19', NULL, NULL, '1730521185195249.jpg', NULL, NULL, 148, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 17:33:28', '2024-10-26 01:48:51', '0'),
(22, 'โครงการพัฒนาความรู้บุคลากรเพื่อสนับสนุนงานด้านศิลปะและวัฒนธรรม “ส่งเสริมทักษะการเตรียมสถานที่อย่างมืออาชีพ” เพื่อให้บุคลากรมีความรู้เกี่ยวกับการจัดดอกไม้แบบต่างๆ เพื่อส่งเสริมให้บุคลากรมีทักษะเกี่ยวกับการจัดดอกไม้', 'โครงการพัฒนาความรู้บุคลากรเพื่อสนับสนุนงานด้านศิลปะและวัฒนธรรม “ส่งเสริมทักษะการเตรียมสถานที่อย่างมืออาชีพ” เพื่อให้บุคลากรมีความรู้เกี่ยวกับการจัดดอกไม้แบบต่างๆ เพื่อส่งเสริมให้บุคลากรมีทักษะเกี่ยวกับการจัดดอกไม้', 'acti-1730528539460904.text', '2022-04-19', NULL, NULL, '1730528539467045.jpg', NULL, NULL, 101, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 19:30:21', '2024-10-24 02:45:42', '0'),
(23, 'โครงการส่งเสริมการบูรณาการองค์ความรู้ด้านศิลปวัฒนธรรม สิ่งแวดล้อม ภูมิปัญญาท้องถิ่น เรื่องจิตรกรรมฝาผนังวัดจันทบุรี', 'โครงการส่งเสริมการบูรณาการองค์ความรู้ด้านศิลปวัฒนธรรม สิ่งแวดล้อม ภูมิปัญญาท้องถิ่น เรื่องจิตรกรรมฝาผนังวัดจันทบุรี', 'acti-1730528603998609.text', '2022-04-19', NULL, NULL, '1730528604004263.jpg', NULL, NULL, 112, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 19:31:23', '2024-10-13 01:48:40', '0'),
(24, 'การฝึกอบรม “การป้องกันอัคคีภัยและการระงับอัคคีภัยในอาคาร” ณ สำนักวิทยบริการและเทคโนสารสนเทศ มหาวิทยาลัยราชภัฏเทพสตรี', 'การฝึกอบรม “การป้องกันอัคคีภัยและการระงับอัคคีภัยในอาคาร” ณ สำนักวิทยบริการและเทคโนสารสนเทศ มหาวิทยาลัยราชภัฏเทพสตรี', 'acti-1730528718521417.text', '2022-04-19', NULL, NULL, '1730528718526839.jpg', NULL, NULL, 98, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 19:33:12', '2024-10-15 12:27:56', '0'),
(25, 'โครงการบูรณาการส่งเสริมการบูรณาการองค์ความรู้ด้านศิลปะและวัฒนธรรมสิ่งแวดล้อมภูมิปัญญาท้องถิ่น การอบรมเชิงปฏิบัติการ “การสร้างแบรนด์และการออกแบบตราสัญลักษณ์ให้กับผลิตภัณฑ์ท้องถิ่น”', 'โครงการบูรณาการส่งเสริมการบูรณาการองค์ความรู้ด้านศิลปะและวัฒนธรรมสิ่งแวดล้อมภูมิปัญญาท้องถิ่น การอบรมเชิงปฏิบัติการ “การสร้างแบรนด์และการออกแบบตราสัญลักษณ์ให้กับผลิตภัณฑ์ท้องถิ่น”', 'acti-1730528801020425.text', '2022-04-19', NULL, NULL, '1730528801025624.jpg', NULL, NULL, 76, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 19:34:31', '2024-08-14 17:32:42', '0'),
(26, 'งานศิลปวัฒนธรรมอุดมศึกษา ครั้งที่ 20  "ข่วงวัฒนธรรมล้ำค่า สืบสานมรดกภูมิปัญญาของแผ่นดิน" ร่วมแลกเปลี่ยนรู้ศิลปะการแสดงพื้นบ้าน 4 ภาค', 'งานศิลปวัฒนธรรมอุดมศึกษา ครั้งที่ 20 \r\n"ข่วงวัฒนธรรมล้ำค่า สืบสานมรดกภูมิปัญญาของแผ่นดิน" ร่วมแลกเปลี่ยนรู้ศิลปะการแสดงพื้นบ้าน 4 ภาค', 'acti-1730528990893595.text', '2022-04-19', NULL, NULL, '1730528990899150.jpg', NULL, NULL, 92, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 19:37:32', '2024-10-15 05:12:30', '0'),
(27, 'โครงการเสวนาวิชาการ สืบสานงานศิลป์ แผ่นดินสมเด็จพระนารายณ์มหาราช เรื่อง “สรรพตำราและองค์ความรู้บนแผ่นดินสมเด็จพระนารายณ์มหาราช”', 'โครงการเสวนาวิชาการ สืบสานงานศิลป์ แผ่นดินสมเด็จพระนารายณ์มหาราช เรื่อง “สรรพตำราและองค์ความรู้บนแผ่นดินสมเด็จพระนารายณ์มหาราช”', 'acti-1730529104696121.text', '2022-04-19', NULL, NULL, '1730529104701614.jpg', NULL, NULL, 116, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 19:39:20', '2024-10-14 20:54:16', '0'),
(28, 'การประชุมใหญ่สามัญสภาศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏแห่งประเทศไทย ประจำปี 2565 ในงาน“100 ปี ราชภัฏพิบูลสงคราม เทิดไท้องค์ราชัน ” เนื่องในวาระโอกาส ครบรอบ 100 ปี วันสถาปนามหาวิทยาลัยราชภัฏพิบูลสงคราม', 'การประชุมใหญ่สามัญสภาศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏแห่งประเทศไทย ประจำปี 2565 ในงาน“100 ปี ราชภัฏพิบูลสงคราม เทิดไท้องค์ราชัน ” เนื่องในวาระโอกาส ครบรอบ 100 ปี วันสถาปนามหาวิทยาลัยราชภัฏพิบูลสงคราม', 'acti-1730529208734358.text', '2022-04-19', NULL, NULL, '1730529208739527.jpg', NULL, NULL, 117, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 19:41:00', '2024-10-17 12:51:09', '0'),
(29, 'กิจกรรมทำบุญกลางบ้าน สืบสานประเพณีสงกรานต์ วันที่ 12 เมษายน 2565 ณ บริเวณลานธรรม และ ห้องโถง ชั้น 1 อาคารรัตนเทพสตรี', 'กิจกรรมทำบุญกลางบ้าน สืบสานประเพณีสงกรานต์ วันที่ 12 เมษายน 2565 ณ บริเวณลานธรรม และ ห้องโถง ชั้น 1 อาคารรัตนเทพสตรี', 'acti-1730529278496535.text', '2022-04-19', NULL, NULL, '1730529278501822.jpg', NULL, NULL, 91, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-04-18 19:42:06', '2024-10-20 03:48:51', '0'),
(30, 'โครงการประชุมเชิงปฏิบัติการทบทวนนโยบายและแผนเพื่อการพัฒนามหาวิทยาลัย (Retreat)', 'โครงการประชุมเชิงปฏิบัติการทบทวนนโยบายและแผนเพื่อการพัฒนามหาวิทยาลัย (Retreat)', 'acti-1730690497009725.text', '2022-04-21', NULL, NULL, '1730690497075753.jpg', NULL, NULL, 102, 'โครงการประชุมเชิงปฏิบัติการทบทวนนโยบายและแผนเพื่อการพัฒนามหาวิทยาลัย (Retreat)', 'โครงการประชุมเชิงปฏิบัติการทบทวนนโยบายและแผนเพื่อการพัฒนามหาวิทยาลัย (Retreat)', 'โครงการประชุมเชิงปฏิบัติการทบทวนนโยบายและแผนเพื่อการพัฒนามหาวิทยาลัย (Retreat)', '2001:3c8:c01:2:23::5db', '2022-04-20 14:24:36', '2024-10-20 05:56:20', '0'),
(31, 'การเสวนาทางวิชาการเพื่อดำเนินการจัดทำแผนพัฒนาการท่องเที่ยว อำเภอพระพุทธบาท​ จังหวัดสระบุรี', 'การเสวนาทางวิชาการเพื่อดำเนินการจัดทำแผนพัฒนาการท่องเที่ยว\r\nอำเภอพระพุทธบาท​ จังหวัดสระบุรี', 'acti-1733251862207017.text', '2022-05-19', NULL, NULL, '1733251862212038.jpg', NULL, NULL, 116, 'การเสวนาทางวิชาการเพื่อดำเนินการจัดทำแผนพัฒนาการท่องเที่ยว อำเภอพระพุทธบาท​ จังหวัดสระบุรี', 'การเสวนาทางวิชาการเพื่อดำเนินการจัดทำแผนพัฒนาการท่องเที่ยว อำเภอพระพุทธบาท​ จังหวัดสระบุรี', 'การเสวนาทางวิชาการเพื่อดำเนินการจัดทำแผนพัฒนาการท่องเที่ยว อำเภอพระพุทธบาท​ จังหวัดสระบุรี', '2001:3c8:c01:2:23::5db', '2022-05-18 20:56:24', '2024-10-20 03:12:26', '0'),
(32, 'โครงการพัฒนาความรู้บุคลากรเพื่อสนับสนุนงานด้านศิลปะและวัฒนธรรม', 'โครงการพัฒนาความรู้บุคลากรเพื่อสนับสนุนงานด้านศิลปะและวัฒนธรรม', 'acti-1733311086307396.text', '2022-05-20', NULL, NULL, '1733311086313850.jpg', NULL, NULL, 266, 'โครงการพัฒนาความรู้บุคลากรเพื่อสนับสนุนงานด้านศิลปะและวัฒนธรรม', 'โครงการพัฒนาความรู้บุคลากรเพื่อสนับสนุนงานด้านศิลปะและวัฒนธรรม', 'โครงการพัฒนาความรู้บุคลากรเพื่อสนับสนุนงานด้านศิลปะและวัฒนธรรม', '2001:3c8:c01:2:23::5db', '2022-05-19 12:37:45', '2024-10-25 14:50:17', '0'),
