INSERT INTO `networks` (`id`, `title`, `intro`, `file_text`, `date`, `slug`, `image_desktop`, `status`, `file_pdf`, `count_view`, `meta_title`, `meta_description`, `meta_keyword`, `ip_address`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'บันทึกข้อตกลงความร่วมมือว่าด้วยการบริการวิชาการและการศึกษาวิจัยด้านศิลปะ วัฒนธรรม ศาสนา ประเพณี และภูมิปัญญาท้องถิ่น', 'โดยเครือข่ายมหาวิทยาลัยราชภัฏ ระหว่าง สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏ 31 แห่ง วันจันทร์ที่ 12 มิถุนายน พ.ศ. 2560 ณ ห้องสิริราชภัฏ สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏพิบูลสงคราม (ส่วนวังจันน์) จังหวัดพิษณุโลก', 'networks-1760972008943107.text', '2023-03-21', NULL, '1760972008950618.jpg', NULL, '1760972077108598.pdf', 271, 'บันทึกข้อตกลงความร่วมมือว่าด้วยการบริการวิชาการและการศึกษาวิจัยด้านศิลปะ วัฒนธรรม ศาสนา ประเพณี และภูมิปัญญาท้องถิ่น', 'บันทึกข้อตกลงความร่วมมือว่าด้วยการบริการวิชาการและการศึกษาวิจัยด้านศิลปะ วัฒนธรรม ศาสนา ประเพณี และภูมิปัญญาท้องถิ่น', 'บันทึกข้อตกลงความร่วมมือว่าด้วยการบริการวิชาการและการศึกษาวิจัยด้านศิลปะ วัฒนธรรม ศาสนา ประเพณี และภูมิปัญญาท้องถิ่น', '::1', '2023-03-21 03:16:16', '2024-10-25 22:41:30', '0'),
(2, 'บันทึกข้อตกลงความร่วมมือเครือข่ายศิลปวัฒนธรรมมหาวิทยาลัยแห่งประเทศไทย', 'บันทึกข้อตกลงความร่วมมือเครือข่ายศิลปวัฒนธรรมมหาวิทยาลัยแห่งประเทศไทย', 'networks-1760972065037020.text', '2023-03-21', NULL, '1760972065043426.jpg', NULL, '1760972065043235.pdf', 257, 'บันทึกข้อตกลงความร่วมมือเครือข่ายศิลปวัฒนธรรมมหาวิทยาลัยแห่งประเทศไทย', 'บันทึกข้อตกลงความร่วมมือเครือข่ายศิลปวัฒนธรรมมหาวิทยาลัยแห่งประเทศไทย', 'บันทึกข้อตกลงความร่วมมือเครือข่ายศิลปวัฒนธรรมมหาวิทยาลัยแห่งประเทศไทย', '::1', '2023-03-21 03:17:10', '2024-10-25 23:07:15', '0');
