INSERT INTO `reportannuals` (`id`, `title`, `intro`, `file_text`, `date`, `slug`, `image_desktop`, `status`, `file_pdf`, `count_view`, `meta_title`, `meta_description`, `meta_keyword`, `ip_address`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'รายงานประจำปี 2564 สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'รายงานประจำปี 2564 สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'annual-1728019402186659.text', '2022-03-22', NULL, '1728019833222335.jpg', NULL, '1728019402231447.pdf', 226, 'รายงานประจำปี 2564 สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'รายงานประจำปี 2564 สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'รายงานประจำปี 2564 สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', '49.230.84.56', '2022-03-22 02:48:42', '2024-10-12 01:40:24', '0'),
(2, 'การจัดการองค์ความรู้ เรื่อง การจัดดอกไม้ประดิษฐ์', 'เนื่องด้วยสำนักศิลปะและวัฒนธรรม มีการจัดกิจกรรมอบรมสัมมนาและต้องเข้าร่วมประเพณีต่างๆอยู่เป็นประจำ จำเป็นต้องมีการเตรียมวัสดุ อุปกรณ์ สิ่งของที่จำเป็นในการประกอบกิจกรรม', 'annual-1741302747282136.text', '2022-08-16', NULL, '1741302747287837.jpg', NULL, '1741302821665117.pdf', 205, 'การจัดการองค์ความรู้ เรื่อง การจัดดอกไม้ประดิษฐ์', 'การจัดการองค์ความรู้ เรื่อง การจัดดอกไม้ประดิษฐ์', 'การจัดการองค์ความรู้ เรื่อง การจัดดอกไม้ประดิษฐ์', '2001:3c8:c01:2:23::5db', '2022-08-15 17:41:47', '2024-10-10 01:36:55', '0'),
(3, 'รายงานผลการประเมินคุณภาพการศึกษาภายใน ประจำปีการศึกษา 2564', 'รายงานผลการประเมินคุณภาพการศึกษาภายใน (Committee Assessment Report : CAR) ระดับหน่วยงานตามโครงสร้างของมหาวิทยาลัยราชภัฏเทพสตรี', 'annual-1752978885447505.text', '2022-12-23', NULL, '1752978885562485.jpg', NULL, '1752978885558709.pdf', 216, NULL, NULL, NULL, '172.16.108.11', '2022-12-22 14:49:00', '2024-10-10 03:40:48', '0'),
(4, 'รายงานผลการวิเคราะห์ความพึงพอใจคุณภาพการบริหารจัดการ สำหรับนักศึกษาและผู้รับบริการภายนอก ประจำปี 2565', 'รายงานผลการวิเคราะห์ความพึงพอใจคุณภาพการบริหารจัดการ\r\nสำหรับนักศึกษาและผู้รับบริการภายนอก\r\nประจำปี 2565', 'annual-1752980492514811.text', '2022-12-23', NULL, '1752980492520463.jpg', NULL, '1752980492518243.pdf', 226, NULL, NULL, NULL, '172.16.108.11', '2022-12-22 15:14:32', '2024-10-18 18:02:45', '0');
INSERT INTO `researchs` (`id`, `title`, `author`, `type`, `keyword`, `year`, `published`, `intro`, `file_text`, `date`, `slug`, `image_desktop`, `status`, `file_pdf`, `count_view`, `meta_title`, `meta_description`, `meta_keyword`, `ip_address`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'การศึกษาผลงานจิตรกรรมฝาผนัง ในพระอุโบสถวัดสมุหประดิษฐาราม อ.เสาไห้ จ.สระบุรี', 'ผศ.ดร.จุติรัช อนุกูล', '1', '#จิตรกรรมฝาผนัง #วัดสำคัญ', '2565', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'บทคัดย่อ\r\n               การศึกษาผลงานจิตรกรรมฝาผนังในพระอุโบสถวัดสมุหประดิษฐาราม อำเภอเสาไห้ จังหวัดสระบุรี\r\nมีวัตถุประสงค์เพื่อ ศึกษาวิเคราะห์ผลงานจิตรกรรมฝาผนังของวัดสมุหประดิษฐาราม ในประเด็นเรื่องราว ความเชื่อ การจัดวางภาพ ตำแหน่งของภาพ และปรากฎการณ์ร่วมสมัยในงานจิตรกรรม\r\n                  ผลการวิจัยพบว่า พระอุโบสถวัดสมุหประดิษฐาราม สร้างราวรัชกาลพระบาทสมเด็จพระนั่งเกล้า-เจ้าอยู่หัวรัชกาลที่ 3 แล้วเสร็จในสมัยรัชกาลที่ 4 บูรณะซ่อมแซมในสมัยรัชกาลที่ 5 และวาดภาพจิตรกรรมเพิ่มเติม  จิตรกรใช้เทคนิคการวาดภาพแบบไทยประเพณี ผสมผสานกับเทคนิคการวาดภาพแบบจีนและตะวันตก เป็นเรื่องราววรรณคดีที่มีสอดแทรกการเรื่องราวชีวิตของชาวบ้านและศิลปวัฒนธรรมแบบจีน \r\n                      1.  ประเด็นเกี่ยวกับเรื่องราว ความเชื่อ ภาพจิตรกรรมที่พบภายในพระอุโบสถ วัดสมุหประดิษฐาราม เป็นเรื่องราวของวรรณคดี 2 เรื่อง คือ เรื่องหลวิชัย คาวีและสมุทรโฆษ ซึ่งแตกต่างจากภาพจิตรกรรมฝาผนังโดยทั่วไปที่นิยมวาดภาพพุทธประวัติ มีความเชื่อเรื่องการทำดีได้ดีทำชั่วได้ชั่วจากภาพพระมาลัยเสด็จโปรดสัตว์นรก ความเชื่อเกี่ยวกับสิ่งเหนือธรรมชาติจากประเพณีแห่กระทงเสียผีและการแห่บั้งไฟขอฝน                      \r\n                      2.  การจัดวางภาพและตำแหน่งของภาพ ภาพจิตรกรรมในพระอุโบสถวัดสมุหประดิษฐารามมีการจัดวางภาพดังนี้ ผนังด้านหลังพระพุทธรูปประธานเขียนภาพการละเล่น วิถีชีวิตชาวไทยวนและพระมาลัยโปรดสัตว์นรก ด้านตรงข้ามพระประธานเขียนภาพประเพณีการแห่บั้งไฟและการแห่กระทงเสียผี ภาพผนังข้างด้านขวามือพระประธานเขียนภาพวรรณคดีเรื่อง หลวิชัย คาวี ผนังสกัดซ้ายมือพระประธานเขียนรูปวรรณคดีเรื่องสมุทรโฆษ บริเวณคอสองทั้งสี่ด้านเขียนภาพลวดลายพุ่มข้าวบิณฑ์ก้านแย่ง \r\n                     3.  ปรากฏการณ์ร่วมสมัยในงานจิตรกรรมฝาผนัง ภาพจิตรกรรมในพระอุโบสถวัดสมุหประดิษฐารามได้แสดงให้เห็นถึงวิถีชีวิตร่วมสมัยของคนพื้นถิ่นกับวัฒนธรรมจีนได้อย่างชัดเจน ส่วนหลักของภาพจิตรกรรมฝาผนังในพระอุโบสถวัดสมุหประดิษฐาราม นอกจากจะเขียนภาพเรื่องราวของวรรณคดีแล้ว จิตรกรยังได้สอดแทรกเรื่องราวร่วมสมัยไว้เป็นส่วนรองหรือส่วนย่อยอีกด้วย ไม่ว่าจะเป็นประเพณี วิถีชีวิต วัฒนธรรม ความเชื่อ การแต่งกาย อาคารบ้านเรือนแบบจีน เรือสำเภา เรือกำปั่นตะวันตกเป็นต้น ส่วนการได้รับอิทธิพลตะวันตกคือการเขียนภาพแบบทัศนียภาพมีระยะใกล้ไกลซึ่งผู้เริ่มต้นในประเทศไทยคือจิตรกรขรัวอินโข่ง\r\n                     ข้อเสนอแนะควรทำการศึกษาภาพจิตรกรรมในวัดแหล่งอื่นที่มีอายุหรือการสร้างในสมัยเดียวกันเพื่อเปรียบเทียบ รูปแบบ แนวคิด วิธีการนำเสนอ เพื่อให้เห็นถึงความสัมพันธ์หรือความแตกต่าง หรือหากต้องการศึกษาเพื่อการอนุรักษ์ ควรทำการศึกษาผลงานจิตรกรรมฝาผนังภายในจังหวัดสระบุรีที่มีคุณค่าและกำลังจะสูญหายไป', NULL, '2022-04-05', NULL, '1729259072485878.jpg', NULL, NULL, 198, NULL, NULL, NULL, '43.249.71.209', '2022-03-21 17:17:12', '2024-10-22 05:30:50', '0'),
(2, 'การศึกษามรดกทางวัฒนธรรม : การอนุรักษ์และการใช้ประโยชน์ อาคารสถาปัตยกรรมสมัยใหม่ในเมืองเก่าลพบุรี', 'ผศ.วิไลวรรณ ฉ่ำพิรุณ, อาจารย์ภาคภูมิ เฉลิมวัฒน์', '2', '#มรดกทางวัฒนธรรม #การอนุรักษ์ #สถาปัตยกรรมสมัยใหม่ #จอมพลป.พิบูลสงคราม', '2565', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'ชื่อโครงการการศึกษา    	:  มรดกทางวัฒนธรรม : การอนุรักษณ์และการใช้ประโยชน์\r\n                                           อาคารสถาปัตยกรรม สมัยใหม่ในเมืองเก่าลพบุรี\r\nชื่อคณะผู้ศึกษา		:  ผศ.วิไลวรรณ ฉ่ำพิรุณ , อาจารย์ภาคภูมิ เฉลิมวัฒน์\r\nปีงบประมาณ           	:  ๒๕๖๕\r\n\r\nการศึกษาในครั้งนี้เป็นการศึกษาเชิงประวัติศาสตร์และเชิงสำรวจ มีวัตถุประสงค์เพื่อ \r\n(๑) เพื่อศึกษาการอนุรักษ์และการใช้ประโยชน์อาคารสถาปัตยกรรมสมัยใหม่ในเมืองเก่าลพบุรี \r\n(๒) เพื่อเผยแพร่องค์ความรู้เกี่ยวกับคุณค่าและความสำคัญของสถาปัตยกรรมสมัยใหม่ (๓) เพื่อนำเสนอข้อมูลการอนุรักษ์และการใช้ประโยชน์อาคารสถาปัตยกรรมสมัยใหม่ในเมืองเก่าลพบุรี \r\n          คณะผู้ศึกษา ใช้วิธี ศึกษาค้นคว้าข้อมูลเบื้องต้นจากเอกสารด้านประวัติศาสตร์ ด้านสถาปัตยกรรม ด้านมรดกทางวัฒนธรรม การอนุรักษ์สถาปัตยกรรมทั้งในประเทศและต่างประเทศ รวมทั้งการลงพื้นที่ภาคสนามสำรวจการใช้ประโยชน์อาคารในปัจจุบัน และสัมภาษณ์ความคิดเห็นเรื่องการอนุรักษ์ของ\r\nผู้อยู่อาศัยและผู้ครอบครอง \r\n         การวิเคราะห์ข้อมูล คณะผู้ศึกษาได้รวบรวมข้อมูลที่ได้จากเอกสารต่างๆ และนำมาวิเคราะห์ร่วมกับข้อมูลผลการสำรวจสภาพปัจจุบันและการใช้ประโยชน์อาคารที่เป็นสถาปัตยกรรมสมัยใหม่ \r\nจากการศึกษา พบว่า อาคารบางแห่งอยู่ในสภาพเดิมเกือบสมบูรณ์ ยังคงความสง่างาม ได้รับ\r\nการอนุรักษ์ ดูแล รักษาไว้อย่างดีจากผู้เกี่ยวข้อง แต่ยังมีอาคารบางแห่งอยู่ในสภาวะปัจจัยเสี่ยงต่อความเสื่อมโทรม ยังขาดการรับรู้องค์ความรู้เกี่ยวกับความเป็นมาและความสำคัญของสถาปัตยกรรมสมัยใหม่ เป็นเหตุให้หลายอาคารถูกละเลยถึงแม้ว่าหลายอาคารได้รับการขึ้นทะเบียนว่าเป็นอาคารอันควรค่า\r\nแก่การอนุรักษ์ ผู้เกี่ยวข้องควรต้องทำการอนุรักษ์และใช้ประโยชน์อาคารที่ยังคงเหลืออยู่ให้เหมาะสม \r\nก่อนที่จะสูญหาย เพราะถือว่าเป็นมรดกทางสถาปัตยกรรมและทางวัฒนธรรมจองชาติ', NULL, '2022-04-05', NULL, '1729259088239714.jpg', NULL, '1727984286471142.pdf', 198, NULL, NULL, NULL, '43.249.71.209', '2022-03-21 17:30:33', '2024-10-13 02:25:56', '0'),
(3, 'การสื่อสารเพื่อดำรงอยู่และสืบทอดภูมิปัญญาของผู้ประกอบพิธีศพ (สัปเหร่อ) ตามหลักพุทธศาสนาในจังหวัดลพบุรี', 'ณัฐชา หน่อทอง', '1', 'พิธีกรรมงานศพ, สัปเหร่อ,', '2558', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'การสื่อสารเพื่อดำรงอยู่และสืบทอดภูมิปัญญาของผู้ประกอบพิธีศพ (สัปเหร่อ) ตามหลักพุทธศาสนาในจังหวัดลพบุรี', NULL, '2022-07-30', NULL, '1739768893888817.jpg', NULL, '1739769020207344.pdf', 331, 'การสื่อสารเพื่อดำรงอยู่และสืบทอดภูมิปัญญาของผู้ประกอบพิธีศพ (สัปเหร่อ) ตามหลักพุทธศาสนาในจังหวัดลพบุรี', 'การสื่อสารเพื่อดำรงอยู่และสืบทอดภูมิปัญญาของผู้ประกอบพิธีศพ (สัปเหร่อ) ตามหลักพุทธศาสนาในจังหวัดลพบุรี', 'การสื่อสารเพื่อดำรงอยู่และสืบทอดภูมิปัญญาของผู้ประกอบพิธีศพ (สัปเหร่อ) ตามหลักพุทธศาสนาในจังหวัดลพบุรี', '2001:3c8:c01:2:23::5db', '2022-07-29 19:21:50', '2024-10-27 09:25:05', '0'),
(4, 'การศึกษาภูมิปัญญาการสานพัดไม้ไผ่ของชุมชน อ.บ้านแพรก จ.พระครศรีอยุธยา ตามแนวคิดคติชนวิทยาและอรรถศาสตร์ชาติพันธุ์', 'พิมพ์ระวี เรืองวัฒกี', '1', 'การสารพัดไม้ไผ่  พัดไม้ไผ่', '2558', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'ภูมิปัญญาการสานพัดไม้ไผ่ของชุมชนอำเภอบ้านแพรก จังหวัดพระนครศรีอยุธยา มีประวัติการสานมากกว่า 80 ปี  เป็นพัดที่มีเอกลักษณ์ คือ สีสดสวยงาม ลวดลายหลากหลาย เนื่องจากเส้นตอกเล็ก ลายจึงละเอียดประณีต และ มีความคงทน เป็นสินค้าหนึ่งตำบลหนึ่งผลิตภัณฑ์ที่สร้างรายได้ให้คนในชุมชนมาช้านาน อย่างไรก็ตามภูมิปัญญาการสานพัดนี้กำลังอยู่ในภาวะน่าเป็นห่วงเนื่องจากมีผู้สืบทอดน้อยลงเรื่อยๆ ด้วยสาเหตุดังกล่าวงานวิจัยนี้จึงมีวัตถุประสงค์เพื่อศึกษาและเก็บภูมิปัญญาท้องถิ่นโดยวิธีการทางคติชนวิทยาและอรรถศาสตร์ชาติพันธุ์  ผลการศึกษาด้านคติชนวิทยาพบว่าการสานพัดไม้ไผ่ในชุมชนนี้มีการสืบทอดด้วยการสอนเป็นรายบุคคลโดยไม่มีการบันทึก ลายพัดไม้ไผ่ที่พบได้แก่ลายดั้งเดิมและลายใหม่ โดยลายดั้งเดิมมี 19 ลาย แบ่งออกเป็นลายพื้นฐาน (ลายขัด) 2 ลาย ได้แก่ลายสองและลายสาม และลายยกดอก 17 ลายได้แก่ ลายไทย ลายดอกโสร่ง ลายดอกสี่ ลายดอกเก้า ลายเครือวัลย์ ลายเครือวัลย์ปลอม ลายไข่ปลา ลายขั้นบันได ลายนกแก้วคู่ ลายพูมะเฟือง ลายบั้ง (อินทรธนู) ลายเข็มขัดนาก ลายกังหัน ลายดอกดาว ลายรังแตน ลายหมากฮอส และลายดาวล้อมเดือน และลายใหม่ได้แก่ ลายอักษร ก ถึง ฮ ลายตัวเลขไทยและตัวเลขอารบิค\r\n		จากการวิเคราะห์ชื่อลายพัดดั้งเดิม (ลายยกดอก) 17 ลาย ด้านอรรถศาสตร์ชาติพันธุ์ด้วยวิธีวิเคราะห์องค์ประกอบ พบว่าชื่อลายพัดดั้งเดิมแตกต่างกันใน 7 มิติ ได้แก่ “รูปกากบาท” “รูปสี่เหลี่ยม” “รูปสามเหลี่ยม” “รูปวงกลม” “รูปหัวใจ” “รูปเครื่องหมายดอกจัน” และ “รูปจุด” ผลการวิเคราะห์ด้านวัฒนธรรมพบว่าลายพัดสามารถสะท้อนวิถีชีวิตของชาวบ้านได้ โดยวัฒนธรรมที่สะท้อนออกมาจากการลวดลายของพัดไม้ไผ่แสดงให้เห็นถึงการอยู่ใกล้ชิดกับธรรมชาติของคนในชุมชน เช่น ลายดอกสี่ ลายดอกเก้า ลายเครือวัลย์ สะท้อนวิถีชีวิตที่เกี่ยวข้องกับธรรมชาติ  ลายไทย ลายอินทรธนู และลายเข็มขัดนาก สะท้อนวิถีชีวิตที่เกี่ยวข้องกับวัฒนธรรมทางวัตถุ', NULL, '2022-07-30', NULL, '1739769362473205.jpg', NULL, '1739769362471443.pdf', 340, 'การศึกษาภูมิปัญญาการสานพัดไม้ไผ่ของชุมชน อ.บ้านแพรก จ.พระครศรีอยุธยา ตามแนวคิดคติชนวิทยาและอรรถศาสตร์ชาติพันธุ์', 'การศึกษาภูมิปัญญาการสานพัดไม้ไผ่ของชุมชน อ.บ้านแพรก จ.พระครศรีอยุธยา ตามแนวคิดคติชนวิทยาและอรรถศาสตร์ชาติพันธุ์', 'การศึกษาภูมิปัญญาการสานพัดไม้ไผ่ของชุมชน อ.บ้านแพรก จ.พระครศรีอยุธยา ตามแนวคิดคติชนวิทยาและอรรถศาสตร์ชาติพันธุ์', '2001:3c8:c01:2:23::5db', '2022-07-29 19:29:17', '2024-10-25 23:20:28', '0'),
(5, 'ระบบสารสนเทศทางภูมิศาสตร์เพื่อการส่งเสริมการท่องเที่ยววัดในอำเภอตาคลี จังหวัดนครสวรรค์', 'รังสิพัฒน์ ยงยุทธวิชัยและคณะ', '1', 'การท่องเที่ยววัด, ระบบสารสนเทศทางภูมิศาสตร์', '2560', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'ระบบสารสนเทศทางภูมิศาสตร์เพื่อการส่งเสริมการท่องเที่ยววัดในอำเภอตาคลี จังหวัดนครสวรรค์', NULL, '2022-07-30', NULL, '1739769829558880.jpg', NULL, '1739769829557661.pdf', 154, 'ระบบสารสนเทศทางภูมิศาสตร์เพื่อการส่งเสริมการท่องเที่ยววัดในอำเภอตาคลี จังหวัดนครสวรรค์', 'ระบบสารสนเทศทางภูมิศาสตร์เพื่อการส่งเสริมการท่องเที่ยววัดในอำเภอตาคลี จังหวัดนครสวรรค์', 'ระบบสารสนเทศทางภูมิศาสตร์เพื่อการส่งเสริมการท่องเที่ยววัดในอำเภอตาคลี จังหวัดนครสวรรค์', '2001:3c8:c01:2:23::5db', '2022-07-29 19:36:42', '2024-10-13 06:29:24', '0'),
(6, 'ศิลปะการออกแบบ ลวดลายผ้า ด้วยการบีบ รัด มัด ย้อมจากสีธรรมชาติ', 'ปวีร์นุช พิริยเศรษฐ์ู', '1', 'ผ้ามัดย้อม, การย้อมสีธรรมชาติ', '2561', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'ศิลปะการออกแบบ ลวดลายผ้า ด้วยการบีบ รัด มัด ย้อมจากสีธรรมชาติ', NULL, '2022-07-30', NULL, '1739770323279885.jpg', NULL, '1739770323278923.pdf', 258, 'ศิลปะการออกแบบ ลวดลายผ้า ด้วยการบีบ รัด มัด ย้อมจากสีธรรมชาติ', 'ศิลปะการออกแบบ ลวดลายผ้า ด้วยการบีบ รัด มัด ย้อมจากสีธรรมชาติ', 'ศิลปะการออกแบบ ลวดลายผ้า ด้วยการบีบ รัด มัด ย้อมจากสีธรรมชาติ', '2001:3c8:c01:2:23::5db', '2022-07-29 19:44:33', '2024-10-12 10:19:37', '0'),
(7, 'การศึกษาจิตรกรราฝาผนังวัดม่วง อ.อินทร์บุรี จ.สิงห์บุรี', 'ผศ.ดร.จุติรัช อนุกูล', '2', 'จิตรกรรมฝาผนัง', '2563', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'การศึกษาจิตรกรราฝาผนังวัดม่วง อ.อินทร์บุรี จ.สิงห์บุรี', NULL, '2022-07-30', NULL, '1739770754277855.jpg', NULL, '1739770754242414.pdf', 222, 'การศึกษาจิตรกรราฝาผนังวัดม่วง อ.อินทร์บุรี จ.สิงห์บุรี', 'การศึกษาจิตรกรราฝาผนังวัดม่วง อ.อินทร์บุรี จ.สิงห์บุรี', 'การศึกษาจิตรกรราฝาผนังวัดม่วง อ.อินทร์บุรี จ.สิงห์บุรี', '2001:3c8:c01:2:23::5db', '2022-07-29 19:51:24', '2024-10-22 19:52:02', '0'),
(8, 'นิทรรศการออนไลน์ เทิดพระเกียรติ พระบาทสมเด็จพระบรมชนกาธิเบศร มหาภูมิพลอดุลยเดชมหาราช บรมนาถบพิตร  13 ตุลาคม 2565', 'สาขา : การจัดการธุรกิจดิจิทัล   คณะ  :  วิทยาการจัดการ', '2', 'นิทรรศการออนไลน์ เทิดพระเกียรติ พระบาทสมเด็จพระบรมชนกาธิเบศร มหาภูมิพลอดุลยเดชมหาราช บรมนาถบพิตร  13 ตุลาคม 2565', '2565', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี แสดงนิทรรศการออนไลน์ เทิดพระเกียรติ พระบาทสมเด็จพระบรมชนกาธิเบศร มหาภูมิพลอดุลยเดชมหาราช บรมนาถบพิตร (รัชกาลที่ 9) \r\n\r\nผลงานโดย\r\nสาขา : การจัดการธุรกิจดิจิทัล  \r\nคณะ  :  วิทยาการจัดการ\r\n\r\nนางสาวภัคคิณี  เข็มดี ​​\r\n    รหัสนักศึกษา 64172980108\r\nนางสาวภาสิณี  เข็มดี ​​\r\n    รหัสนักศึกษา 64172980109\r\nนางสาวเสาวรัตน์  ปานขาว ​\r\n    รหัสนักศึกษา 64172980112\r\nนางสาวศุภลักษณ์  ทองสกุล ​\r\n    รหัสนักศึกษา 64172980115\r\nนางสาวพนิดา  อรรคจันทร์ ​\r\n    รหัสนักศึกษา 64172980122\r\nนางสาววรรณนิภา ยอดคำ ​\r\n    รหัสนักศึกษา 64172980124\r\nนางสาวสุชานรี จันทร์ทับพวง ​\r\n    รหัสนักศึกษา 64172980129\r\nนางสาวกานต์พิชชา ช่วยชิด ​\r\n    รหัสนักศึกษา 64172980132', NULL, '2022-10-12', NULL, '1746352530906914.jpg', NULL, '1746456077714459.pdf', 242, NULL, NULL, NULL, '2001:3c8:c01:2:23::5db', '2022-10-10 11:25:56', '2024-10-22 13:37:46', '0'),
(10, 'ผ้าทอมัดหมี่ บ้านโคกเจริญ อ.โคกเจริญ จ.ลพบุรี', 'ผลงานออกแบบโดยอาจารย์วินัย ปัจฉิม', 'บทความ', 'ผ้าทอมัดหมี่ บ้านโคกเจริญ อ.โคกเจริญ จ.ลพบุรี', '2566', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'research-1766026829341796.text', '2023-05-16', NULL, '1766036182892930.png', NULL, NULL, 298, 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', '172.16.108.11', '2023-05-15 22:20:29', '2024-10-24 02:59:30', '0'),
(11, 'การศึกษาผลงานจิตรกรรมฝาผนังในอุโบสถวัดพระปรางค์มุนี อำเภอเมืองสิงห์บุรี จังหวัดสิงห์บุรี', 'ผศ.ดร.จุติรัช อนุกูล', 'งานวิจัย', 'จิตรกรรมฝาผนัง', '2566', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'การศึกษาผลงานจิตรกรรมฝาผนังในอุโสถวัดพระปรางค์มุณี อำเภอเมืองสิงห์บุรี จังหวัดสิงห์บุรีมีวัตถุประสงค์เพื่อ ศึกษาวิเคราะห์ผลงานจิตรกรรมฝาผนังของวัดพระปรางค์มุณี ในประเด็นเรื่องราว ความเชื่อ การจัดวางภาพ ตำแหน่งของภาพ และปรากฎการณ์ร่วมสมัยในงานจิตรกรรม\r\n          ผลการวิจัยพบว่า\r\n          อุโบสถวัดพระปรางค์มุณี เป็นอาคารก่ออิฐถือปูนไม่ปรากฏร่องรอยหลักฐานว่าสร้างในสมัยใด แต่จากคำบอกเล่าของอดีตเจ้าอาวาสว่าผลงานจิตรกรรมฝาผนังแห่งนี้วาดโดยนายเพ็งเมื่อ\r\nปี พ.ศ.2462 อาจสันนิษฐานได้ว่าอุโบสถหลังนี้อาจสร้างแล้วเสร็จในราวปี พ.ศ.2460-2461 หรืออาจสร้างก่อนหน้านั้น จิตรกรรมในอุโบสถเป็นเรื่องราวพุทธประวัติ ทศชาติชาดกและนรกภูมิ \r\nที่มีรูปแบบไม่เป็นไปตามขนบธรรมเนียมนิยมที่เคยสืบทอดกันมา เขียนโดยช่างเพ็ง จิตรกรพื้นบ้านที่มีผลงานวาดไว้อย่างน้อยสองแห่งในจังหวัดลพบุรี \r\n\r\n1.  ประเด็นเกี่ยวกับเรื่องราว ความเชื่อ ของภาพจิตรกรรม ภาพจิตรกรรมที่พบภายในอุโบสถวัดพระปรางค์มุณี ทั้งหมดยังเป็นความเชื่อแบบดั้งเดิมของพุทธศาสนา เป็นเรื่องราวพุทธประวัติตอนเสด็จออกผนวช ตอนผจญมาร ตอนเสด็จโปรดพุทธมารดาบนสวรรค์ ตอนปราบอสุรินทราหู ภาพทศชาติชาดกสื่อให้เห็นถึงการบำเพ็ญเพียรของพระพุทธเจ้าในด้านทาน ศีล ภาวนาให้เต็มครบทุกบารมี และภาพนรกภูมิสื่อให้เห็นผลของการทำบาปต่างๆเพื่อให้คนละจากการกระทำ\r\nความชั่วเกรงกลัวต่อบาป\r\n2.  การจัดวางภาพและตำแหน่งของภาพ ภาพจิตรกรรมในอุโบสถวัดพระปรางค์มุนี\r\nมีการจัดวางภาพดังนี้ ผนังด้านหลังพระพุทธรูปขวามือประธานเขียนมารผจญ ด้านล่างเขียนภาพปางป่าลิไลย์ ซ้ายมือพระประธานด้านบนเขียนภาพเจดีย์จุฬามณี ด้านล่างเขียนภาพปางไสยาสน์ปราบอสุรินทราหู ภาพตรงข้ามพระประธานซ้ายมือเขียนภาพทรงออกผนวช ขวามือเขียนภาพเสด็จกลับจากดาวดึงส์ ภาพด้านข้างเขียนภาพทศชาติชาดกฝั่งละ 5 ตอน ด้านล่างเขียนภาพนรกภูมิ\r\n         3.  ปรากฏการณ์ร่วมสมัยในงานจิตรกรรมฝาผนัง ภาพจิตรกรรมในอุโบสถวัดพระปรางค์มุณี ได้แสดงให้เห็นถึงวิถีชีวิตของชาวบ้านผสมผสานกับความเจริญในขณะนั้น ส่วนหลักของภาพจิตรกรรมฝาผนังในอุโบสถวัดพระปรางค์มุณี นอกจากจะเขียนภาพเรื่องราวของพุทธประวัติ ทศชาติชาดกและนรกภูมิแล้ว จิตรกรยังได้สอดแทรกเรื่องราวร่วมสมัยไว้เป็นส่วนรองหรือส่วนย่อยอีกด้วยได้แก่ งานสถาปัตยกรรมแบบตะวันตก การแต่งกายของทหารสมัยรัชกาลที่ 5-6 การจัดขบวนทหาร ทรงผมและการแต่งกายของชาวบ้าน การศึกษา วัฒนธรรมการกิน พาหนะการเดินทาง \r\nการล่าสัตว์ การจองจำทำโทษ และขั้นตอนการทำงานของศิลปิน', 'research-1778717908992578.text', '2023-10-04', NULL, '1778788905243942.jpg', NULL, '1778717908992606.pdf', 142, 'การศึกษาผลงานจิตรกรรมฝาผนังในอุโบสถวัดพระปรางค์มุนี อำเภอเมืองสิงห์บุรี จังหวัดสิงห์บุรี', 'การศึกษาผลงานจิตรกรรมฝาผนังในอุโบสถวัดพระปรางค์มุนี อำเภอเมืองสิงห์บุรี จังหวัดสิงห์บุรี', 'การศึกษาผลงานจิตรกรรมฝาผนังในอุโบสถวัดพระปรางค์มุนี อำเภอเมืองสิงห์บุรี จังหวัดสิงห์บุรี', '172.16.108.11', '2023-10-03 00:19:45', '2024-10-07 13:35:22', '0'),
(12, 'การศึกษาผลงานจิตรกรรมฝาผนังในศาลาพระศรีอาริยเมตไตรย  วัดตองปุ อำเภอเมืองลพบุรี จังหวัดลพบุรี', 'ผศ.ดร.จุติรัช อนุกูล', 'งานวิจัย', 'จิตรกรรมฝาผนัง', '2566', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'การศึกษาผลงานจิตรกรรมฝาผนังในศาลาพระศรีอาริยเมตไตรย วัดตองปุ อำเภอเมืองลพบุรี จังหวัดลพบุรี มีวัตถุประสงค์เพื่อศึกษาวิเคราะห์ผลงานจิตรกรรมฝาผนังของวัดตองปุ ในประเด็นเรื่องราว ความเชื่อ การจัดวางภาพ ตำแหน่งของภาพ และปรากฎการณ์ร่วมสมัยในงานจิตรกรรม\r\n	    ผลการวิจัยพบว่า\r\n         ศาลาพระศรีอาริยเมตไตรย วัดตองปุ สร้างในราวรัชกาลพระบาทสมเด็จจอมเกล้าเจ้าอยู่หัวรัชกาลที่ 4  จิตรกรใช้เทคนิคการวาดภาพแบบไทยประเพณี ผสมผสานกับเทคนิคการวาดภาพแบบตะวันตก เป็นเรื่องราวพุทธประวัติที่มีสอดแทรกการเรื่องราวชีวิตของชาวบ้านผสมผสานกับสถาปัตยกรรมความเจริญของเมืองกรุงเทพในขณะนั้น \r\n   	1. ประเด็นเกี่ยวกับเรื่องราว ความเชื่อ ของภาพจิตรกรรมยังเป็นความเชื่อแบบดั้งเดิมของพุทธศาสนา เป็นเรื่องราวพุทธประวัติ จัดเรียงลำดับตามเรื่องพุทธประวัติตามตำราหรือเรื่องเล่าที่สืบทอดต่อกันมา จิตรกรมีจุดมุ่งหมายในการเขียนภาพเพื่อสืบทอดกพระพุทธศาสนาด้วย\r\nการแสดงออกทางศิลปะ ต้องการให้ภาพที่เขียนเป็นเครื่องโน้มน้าวจิตใจของชาวบ้านให้เกิด\r\nความเลื่อมใส ศรัทธาในพุทธศาสนามากยิ่งขึ้น\r\n    	2. การจัดวางภาพและตำแหน่งของภาพ ผนังด้านข้างขวามือพระประธานเขียนภาพ พุทธประวัติเริ่มจากมุมขวาเจ้าชายสิทธัตถะประทับที่ปราสาทสามฤดู เสด็จประพาสนอกเมือง\r\nเห็นเทวทูตทั้ง 4 ทรงหนีออกผนวช ตอน มหาภิเนกษกรมณ์ ศึกษาธรรมกับอาฬารดาบสกับอุทกดาบส นางสุชาดาถวายข้าวมธุปายาส ด้านหลังพระประธานเขียนภาพทรงอธิษฐานลอยถาด เมืองบาดาลของกาฬนาคราช ตอนบิณฑบาต ด้านซ้ายมือพระประธานเขียนภาพทรงโปรดชฎิลสามพี่น้อง ทรงเสด็จโปรดพระบิดาในกรุงกบิลพัสดุ์ ทรงเสด็จเมืองกุสินาราและทรงปรินิพาน ภาพเมืองหลวง\r\nในกรุงเทพฯ ด้านตรงข้ามพระประธานเขียนภาพพระภิกษุปลงอสุภ\r\n   	3. ปรากฏการณ์ร่วมสมัยในงานจิตรกรรมฝาผนัง ได้แสดงให้เห็นถึงปรากฏการณ์ร่วมสมัยของวิถีชีวิตของชาวบ้านผสมผสานกับสถาปัตยกรรมแบบตะวันตกที่มีอิทธิพลอย่างมากในสมัยรัชกาลที่ 4-5  เช่นภาพการแต่งกายของทหารมหาดเล็กรักษาพระองค์ ภาพธงชาติไทย ภาพประตูพระบรมมหาราชวัง ภาพอาคารพาณิชย์ ภาพการแต่งกายแบบชาวบ้าน ภาพเสือ ภาพศิลปะการลงรักปิดทอง ภาพบ้านเรือนในชนบท เป็นต้น\r\n 	ข้อเสนอแนะ ควรทำการศึกษาภาพจิตรกรรมในวัดแหล่งอื่นที่มีอายุหรือการสร้างในสมัยเดียวกันเพื่อเปรียบเทียบ รูปแบบ แนวคิด วิธีการนำเสนอ เพื่อให้เห็นถึงความสัมพันธ์หรือความแตกต่าง หรือหากต้องการศึกษาเพื่อการอนุรักษ์ ควรทำการศึกษาผลงานจิตรกรรมฝาผนัง\r\nภายในจังหวัดลพบุรีที่มีคุณค่าและกำลังจะสูญหายไป', 'research-1778718296786368.text', '2023-10-05', NULL, '1778909597715144.jpg', NULL, '1778718296786392.pdf', 222, 'การศึกษาผลงานจิตรกรรมฝาผนังในศาลาพระศรีอาริยเมตไตรย  วัดตองปุ อำเภอเมืองลพบุรี จังหวัดลพบุรี', 'การศึกษาผลงานจิตรกรรมฝาผนังในศาลาพระศรีอาริยเมตไตรย  วัดตองปุ อำเภอเมืองลพบุรี จังหวัดลพบุรี', 'การศึกษาผลงานจิตรกรรมฝาผนังในศาลาพระศรีอาริยเมตไตรย  วัดตองปุ อำเภอเมืองลพบุรี จังหวัดลพบุรี', '172.16.108.11', '2023-10-03 00:25:55', '2024-10-20 05:42:22', '0'),
(13, 'การศึกษาองค์ความรู้ภูมิปัญญาผ้าหมักโคลนเจ้าพระยา บ้านบางน้ำเชี่ยว ตำบลบางน้ำเชี่ยว อำเภอพรหมบุรี จังหวัดสิงห์บุรี', 'ผศ.วิไลวรรณ ฉ่ำพิรุณ', 'งานวิจัย', 'ผ้าหมักโคลน', '2566', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'การศึกษาวิจัย :  เรื่อง การศึกษาองค์ความรู้ภูมิปัญญาผ้าหมักโคลนเจ้าพระยา บ้านบางน้ำเชี่ยว อำเภอพรหมบุรี  จังหวัดสิงห์บุรีฉบับนี้ เป็นการศึกษาวิจัยเชิงคุณภาพ  มีวัตถุประสงค์เพื่อ ศึกษา\r\nองค์ความรู้ภูมิปัญญาผ้าหมักโคลนเจ้าพระยา บ้านบางน้ำเชี่ยว อำเภอพรหมบุรี จังหวัดสิงห์บุรี \r\nกลุ่มตัวอย่าง โดยการสุ่มตัวอย่างแบบเจาะจง คือ เจ้าของภูมิปัญญาผ้าหมักโคลนเจ้าพระยา \r\nบ้านบางน้ำเชี่ยว และการสังเกตแบบไม่มีส่วนร่วมศูนย์ภูมิปัญญาไทยผ้าหมักโคลนเจ้าพระยา \r\nบ้านบางน้ำเชี่ยว รวบรวมข้อมูลจากเอกสารที่เกี่ยวข้องและจากสื่อต่างๆ การวิเคราะห์ข้อมูลเชิงพรรณนาและวิเคราะห์เนื้อหาจากการสัมภาษณ์แบบเจาะลึก จากเอกสารที่เกี่ยวข้อง ซึ่งผลการศึกษาพบว่า \r\n  1. องค์ความรู้ภูมิปัญญาผ้าหมักโคลนเจ้าพระยา บ้านบางน้ำเชี่ยว เป็นภูมิปัญญาท้องถิ่นที่พบโดยบังเอิญ โดยนางดวงพร อารีย์พันธ์ กระบวนการผลิตใช้ทรัพยากรธรรมชาติคือ โคลนและน้ำฝนเทคนิควิธีเป็นแบบช่างฝีมือที่เรียบง่าย ใช้ความประณีต ใช้ระยะเวลา ไม่พึ่งพาเทคโนโลยี่ขั้นสูง จุดเด่นคือโคลนจากแม่น้ำเจ้าพระยา บ้านบางน้ำเชี่ยว เป็นโคลนที่มีแร่ธาตเหล็กและแม็คนีเซียมผสมอยู่ในเนื้อโคลน \r\nซึ่งทำให้โคลนมีสีเหลืองทอง แตกต่างจากโคลนที่อื่น ๆ ผ้าที่ถูกหมักด้วยน้ำโคลนมีคุณสมบัติโดดเด่น คือ \r\nมีความนุ่ม ลื่น ใส่แล้วเย็นสบาย ช่วยขับสารพิษออกจากร่างกายเวลานุ่งห่ม  เป็นผ้าหมักโคลนที่ปราศจากสารเคมี   \r\n2. แนวทางการสืบสานภูมิปัญญาผ้าหมักโคลนคือ การต่อยอดด้วยการทอด้วยผ้าลายริ้วทอง\r\nและลายพรหมสี่ทิศจากเส้นใยธรรมชาติและการย้อมสีจากวัสดุธรรมชาติ', 'research-1778718578791609.text', '2023-10-05', NULL, '1778909541331492.jpg', NULL, '1778718578791631.pdf', 311, 'การศึกษาองค์ความรู้ภูมิปัญญาผ้าหมักโคลนเจ้าพระยา บ้านบางน้ำเชี่ยว ตำบลบางน้ำเชี่ยว อำเภอพรหมบุรี จังหวัดสิงห์บุรี', 'การศึกษาองค์ความรู้ภูมิปัญญาผ้าหมักโคลนเจ้าพระยา บ้านบางน้ำเชี่ยว ตำบลบางน้ำเชี่ยว อำเภอพรหมบุรี จังหวัดสิงห์บุรี', 'การศึกษาองค์ความรู้ภูมิปัญญาผ้าหมักโคลนเจ้าพระยา บ้านบางน้ำเชี่ยว ตำบลบางน้ำเชี่ยว อำเภอพรหมบุรี จังหวัดสิงห์บุรี', '172.16.108.11', '2023-10-03 00:30:24', '2024-10-24 02:30:47', '0'),
(14, 'เมืองละโว้ในฐานะภาพสะท้อนการเปลี่ยนแปลงโลกทัศน์ ในรัชสมัยสมเด็จพระนารายณ์มหาราช', 'สำนักศิลปะและวัฒนธรรม', 'งานวิจัย', 'สมเด็จพระนารายณ์มหาราช', '2566', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'เมืองละโว้ในฐานะภาพสะท้อนการเปลี่ยนแปลงโลกทัศน์ ในรัชสมัยสมเด็จพระนารายณ์มหาราช', 'research-1778718941442912.text', '2023-10-05', NULL, '1778909434239084.jpg', NULL, '1778718941445997.pdf', 190, 'เมืองละโว้ในฐานะภาพสะท้อนการเปลี่ยนแปลงโลกทัศน์ ในรัชสมัยสมเด็จพระนารายณ์มหาราช', 'เมืองละโว้ในฐานะภาพสะท้อนการเปลี่ยนแปลงโลกทัศน์ ในรัชสมัยสมเด็จพระนารายณ์มหาราช', 'เมืองละโว้ในฐานะภาพสะท้อนการเปลี่ยนแปลงโลกทัศน์ ในรัชสมัยสมเด็จพระนารายณ์มหาราช', '172.16.108.11', '2023-10-03 00:36:10', '2024-10-07 13:47:44', '0'),
(15, 'การศึกษาประวัติความเป็นมาและการพัฒนากิจกรรม การวาดภาพพระบฏ งานทำบุญเมืองลพบุรี', 'ผศ.วิไลวรรณ ฉ่ำพิรุณ', 'งานวิจัย', 'ภาพพระบฏ', '2566', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'การศึกษาเรื่อง “ประวัติความเป็นมาและการพัฒนาการวาดภาพพระบฏงานทำบุญเมืองลพบุรี” นี้มีวัตถุประสงคเพื่อศึกษาประวัติความเป็นมา ขั้นตอนการปฏิบัติ สภาพปญหาและ\r\nแนวทางการพัฒนาการวาดภาพพระบฏงานทำบุญเมืองลพบุรี การศึกษาครั้งนี้ ใชวิธีการวิจัย\r\nเชิงคุณภาพ เก็บรวบรวมข้อมูลจากเอกสารและการตอบแบบสอบถามของผู้เข้าร่วมกิจกรรม \r\n	ผลการศึกษาปรากฏดังนี้\r\n1. ประวัติความเป็นมาของการวาดภาพพระบฏงานทำบุญเมืองลพบุรี การวาดภาพพระบฏเป็นกิจกรรมหนึ่งของงานทำบุญเมืองลพบุรีที่ทางชมรมอนุรักษ์โบราณวัตถุสถานและสิ่งแวดล้อมจังหวัดลพบุรีต้องการให้ สถาบันการศึกษาต่าง ๆ  นักเรียน นักศึกษา เยาวชนได้มีส่วนร่วมใน\r\nงานทำบุญเมืองลพบุรีซึ่งจัดขึ้นเป็นประจำทุกปี จึงได้เพิ่มกิจกรรมการวาดภาพพระบฏขึ้นเมื่อ\r\nปี พ.ศ. 2552  หัวข้อเรื่องที่วาด เป็นเรื่องเกี่ยวกับพระพุทธประวัติ กิจกรรมการวาดภาพพระบฏ\r\nจะมีขึ้นในช่วงเช้าของวันที่มีงานทำบุญเมือง สถานที่จัดงานคือภายในพระนารายณ์ราชนิเวศน์ \r\nเขตพระราชฐานชั้นนอก\r\n2. ประเพณีปฏิบัติ เป็นการวาดภาพที่แตกต่างจากการวาดภาพโดยทั่วไป เป็นการวาดภาพเกี่ยวกับพุทธประวัติและระบายสีด้วยสีน้ำมัน บนผืนผ้าดิบสีขาว หรือสีเหลือง  แบ่งออกเป็นช่อง ๆ ละประมาณ 1.50 เมตร ความยาวของผ้าตามพระชนมายุของพระบาทสมเด็จพระบรมชนกาธิเบศร มหาภูมิพลอดุลยเดชมหาราช บรมนาถบพิตร เพื่อความเป็นสิริมงคลและถวายเป็นพระราชกุศลแด่พระองค์ท่าน การวาดภาพพระบฏนี้จัดขึ้นภายใน เขตพระราชฐานชั้นนอก พระนารายณ์ราชนิเวศน์ ในช่วงเช้าของวันที่มีงานทำบุญเมืองลพบุรี นักเรียน นักศึกษา ครู อาจารย์ จะมาร่วมกันวาดภาพ\r\nพระบฏเป็นทีม เริ่มวาดภาพตั้งแต่ เวลา 09.00 น - 14.00 น เมื่อวาดภาพเสร็จแล้ว มีขบวนแห่ผ้า\r\nพระบฏจากพระนารายณ์ราชนิเวศน์ ผ่านตลาดบนเมือง พระปรางค์สามยอด ศาลพระกาฬ \r\nมายังวัดพระศรีรัตนมหาธาตุเพื่อนำผ้าพระบฏห่มองค์ปรางค์ ถวายเป็นพุทธบูชา\r\n3. สภาพปัญหา มีหลายประการ คือ 1) ด้านสถานที่ในการจัดกิจกรรม เนื่องจากจัดในที่โล่ง บางช่วงมีแสงแดดส่อง มีร่มไม่เพียงพอ \r\n4. แนวทางการสืบสาน ได้แก่ 1) การให้ความรู้เกี่ยวกับความสำคัญของผ้าพระบฏอย่างเป็นรูปธรรมควรเป็นส่วนหนึ่งของกิจกรรม 2) การนำกิจกรรมการวาดภาพพระบฏไปต่อยอดในวิชาศิลปะการวาดภาพและวิชาที่เกี่ยวกับพระพุทธศาสนา 3) การนำผ้าพระบฏไปถวายยังวัดต่าง ๆ ที่แสดงความจำนงในเทศกาลเทศน์มหาชาติ', 'research-1778719100876873.text', '2023-10-05', NULL, '1778909476436806.jpg', NULL, '1778719100876899.pdf', 217, 'การศึกษาประวัติความเป็นมาและการพัฒนากิจกรรม การวาดภาพพระบฏ งานทำบุญเมืองลพบุรี', 'การศึกษาประวัติความเป็นมาและการพัฒนากิจกรรม การวาดภาพพระบฏ งานทำบุญเมืองลพบุรี', 'การศึกษาประวัติความเป็นมาและการพัฒนากิจกรรม การวาดภาพพระบฏ งานทำบุญเมืองลพบุรี', '172.16.108.11', '2023-10-03 00:38:42', '2024-10-09 01:39:15', '0'),
(17, 'การศึกษาผลงานจิตรกรรมฝาผนังในอุโบสถวัดหนองยาวสูง อำเภอเมืองสระบุรี จังหวัดสระบุรี', 'ผศ.ดร.จุติรัช อนุกูล', 'งานวิจัย', 'จิตรกรรมฝาผนัง', '2567', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'การศึกษาผลงานจิตรกรรมฝาผนังในอุโบสถวัดหนองยาวสูงอำเภอเมืองสระบุรีจังหวัดสระบุรี มีวัตถุประสงค์เพื่อศึกษาวิเคราะห์ผลงานจิตรกรรมฝาผนังของวัดหนองยาวสูง  ในประเด็นเรื่องราว ความเชื่อ การจัดวางภาพ ตำแหน่งของภาพ และปรากฎการณ์ร่วมสมัยในงานจิตรกรรม\r\n           ผลการวิจัยพบว่า อุโบสถวัดหนองยาวสูงสร้างราวปลายสมัยรัชกาลที่ 1  พ.ศ. 2350  อาจบูรณะในสมัยรัชกาลที่ 3  และวาดภาพจิตรกรรมเพิ่มเติมในสมัยรัชกาลที่ 4-5  จิตรกรใช้เทคนิคการวาดภาพแบบไทยประเพณี ผสมผสานกับเทคนิคการวาดภาพแบบจีนและตะวันตก\r\n          1. ประเด็นเกี่ยวกับเรื่องราว ความเชื่อ ของภาพจิตรกรรม ภาพจิตรกรรมที่พบภายในอุโบสถของวัดหนองยาวสูง ทั้งหมดยังเป็นความเชื่อแบบดั้งเดิมของพุทธศาสนา เป็นเรื่องราวพุทธประวัติ และทศชาติชาดกตอนพระเวสสันดรชาดก ความเชื่อในการที่จิตรกรนำพุทธประวัติและทศชาติตอนพระเวสสันดรชาดกมาวาดเป็นงานจิตรกรรมในอุโบสถนั้นเพื่อเป็นการสืบทอดพระพุทธศาสนาในการออกบวชของพระพุทธเจ้าและความเชื่อเกี่ยวกับการทำบุญด้วยการให้ทานของชาวไทยวน ที่สืบทอดกันมาว่าได้อานิสงส์มาก หรือการฟังธรรมหรือศึกษาธรรมเรื่องพระเวสสันดร จนจบ ๑๓ กัณฑ์ ก็สามารถอธิษฐานพระนิพพาน หรืออธิษฐานเพื่อไปเกิดในยุคพระศรีอริยเมตไตรยได้ รวมถึงความเชื่อเรื่องนรกสวรรค์ การทำความดีละเว้นความความชั่วการทำบุญอุทิศให้ผู้ตายในตอนพระมาลัยโปรดโลก\r\n        \r\n2.  การจัดวางภาพและตำแหน่งของภาพ ภาพจิตรกรรมในอุโบสถวัดหนองยาวสูง มีการจัดวางภาพดังนี้ ผนังด้านหลังพระพุทธรูปประธานเขียนภาพเจดีย์จุฬามณี ด้านตรงข้ามพระประธานเขียนภาพมารผจญ ภาพจิตรกรรมด้านข้างแบ่งออกเป็น 2 ส่วนคือด้านบนและด้านล่าง ด้านบนเขียนภาพพระเวสสันดรชาดก 13 กัณฑ์ ด้านล่างแบ่งออกเป็นช่องๆเขียนภาพ เรื่องต้นกัลปพฤกษ์ ประเพณีวิถีชาวบ้านชาวไทยวน เรื่องรามเกียรติ์ เรื่องพุทธประวัติตอนมหาภิเนษกรมณ์ เรื่องจันทโครพ เรื่องพระมาลัยโปรดนรกภูมิ เรื่องตำนานต้นมักกะลีผล\r\n\r\n       3. ปรากฏการณ์ร่วมสมัยในงานจิตรกรรมฝาผนัง ภาพจิตรกรรมในอุโบสถวัดหนองยาวสูง ได้แสดงให้เห็นถึงปรากฏการณ์ร่วมสมัยของภาพทหารในสมัยรัชกาลที่ 4- 5 ภาพชาวต่างชาติ  ภาพเรือสำเภา ภาพธงช้างเผือก ภาพหอนาฬิกา ภาพวิถีชีวิตชาวไทยวน เช่น การแต่งกาย ทรงผม ที่อยู่อาศัย ภาพการทำคลอดแบบโบราณ ภาพวงดุริยสตรี หรือเป็นภาพกากในมุมเล็ก ๆ ที่จิตรกรซ่อนไว้เช่นการดูดกัญชาและเรื่องกามรมณ์ เป็นต้น', 'research-1794824972533058.text', '2024-03-29', NULL, '1794824972533482.png', NULL, '1794824972533082.pdf', 16, 'การศึกษาผลงานจิตรกรรมฝาผนังในอุโบสถวัดหนองยาวสูง อำเภอเมืองสระบุรี จังหวัดสระบุรี', 'การศึกษาผลงานจิตรกรรมฝาผนังในอุโบสถวัดหนองยาวสูง อำเภอเมืองสระบุรี จังหวัดสระบุรี', 'การศึกษาผลงานจิตรกรรมฝาผนังในอุโบสถวัดหนองยาวสูง อำเภอเมืองสระบุรี จังหวัดสระบุรี', '172.16.108.11', '2024-03-28 19:14:38', '2024-10-20 05:28:54', '0'),
(19, 'การละเล่นพุ่งเรือ วัดมะขามเรียง ตำบลไผ่ขวาง อำเภอบ้านหมอ จังหวัดสระบุรี : แนวทางการอนุรักษ์และสืบทอด', 'ผู้ช่วยศาสตราจารย์ ศรีสุภา นาคธน , ผู้ช่วยศาสตราจารย์ ธนิดา ภู่แดง, ผู้ช่วยศาสตราจารย์ วนิดา เพิ่มศิริ, นาย ประยงค์ จันทร์ฉาย', 'งานวิจัย', 'การละเล่นพุ่งเรือ  วัดมะขามเรียง', '2567', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'การวิจัยนี้ มีวัตถุประสงค์เพื่อศึกษา 1) ภูมิปัญญาชาวบ้านด้านการทำเรือพุ่ง 2) การละเล่นพุ่งเรือ และ 3) แนวทางการอนุรักษ์ การละเล่นพุ่งเรือของชุมชนวัดมะขามเรียง ตำบลไผ่ขวาง อำเภอบ้านหมอ จังหวัดสระบุรี เป็นการวิจัยเชิงคุณภาพ โดยศึกษาจากประชากรที่เกี่ยวข้องกับการละเล่นพุ่งเรือ ที่กำหนดขึ้นมาอย่างเฉพาะเจาะจง จำนวน 8 คน วิธีการเก็บข้อมูลภาคสนามโดยการสัมภาษณ์แบบเจาะลึก และการสังเกตแบบไม่มีส่วนร่วม \r\n	ผลการศึกษา พบว่า 1) ภูมิปัญญาชาวบ้านด้านการทำเรือพุ่ง ปรากฏทั้งในขั้นตอนการเลือกไม้ไผ่สำหรับทำตัวเรือและขั้นตอนวิธีการทำเรือพุ่ง ซึ่งต้องมีความชำนาญเฉพาะบุคคล 2) ชุมชนวัดมะขามเรียง ตำบลไผ่ขวาง อำเภอบ้านหมอ จังหวัดสระบุรี เป็นเพียงชุมชนเดียวในประเทศไทยที่มีประเพณีการละเล่นพุ่งเรือ มีการสืบสานการละเล่นพุ่งเรือประจำปี ระหว่างวันที่ 13-15 เมษายน ของทุกปี  ในการแข่งขันจะมีการสร้างสนามชั่วคราวสำหรับการแข่งขัน มีการกำหนดประเภทผู้เข้าแข่งขัน มีกติกาในการแข่งขันแบบง่าย ๆ เน้นความสนุกสนาน รื่นเริง และความรักสามัคคีของประชาชนในชุมชน และ 3) แนวทางการอนุรักษ์การละเล่นพุ่งเรือ ผู้นำชุมชนควรสร้างความตระหนักแก่เยาวชน ประชาชน และองค์กรในชุมชน ให้มีความรักและหวงแหนการละเล่นพุ่งเรือ ควรส่งเสริมให้มีการถ่ายทอดองค์ความรู้การทำเรื่อพุ่งและการละเล่นพุ่งเรือให้เยาวชนอย่างจริงจัง หน่วยงานทั้งภาครัฐและเอกชนควรสนับสนุนให้มีการเผยแพร่การละเล่นพุ่งเรือให้กว้างขวางไปยังชุมชนอื่น ๆ รวมทั้งอนุรักษ์และสืบทอดให้คงอยู่สืบไป', 'research-1802639758177245.text', '2024-06-23', NULL, '1802639758177851.jpg', NULL, '1802639758177270.pdf', 19, 'การละเล่นพุ่งเรือ วัดมะขามเรียง ตำบลไผ่ขวาง อำเภอบ้านหมอ จังหวัดสระบุรี : แนวทางการอนุรักษ์และสืบทอด', 'การละเล่นพุ่งเรือ วัดมะขามเรียง ตำบลไผ่ขวาง อำเภอบ้านหมอ จังหวัดสระบุรี : แนวทางการอนุรักษ์และสืบทอด', 'การละเล่นพุ่งเรือ วัดมะขามเรียง ตำบลไผ่ขวาง อำเภอบ้านหมอ จังหวัดสระบุรี : แนวทางการอนุรักษ์และสืบทอด', '172.16.108.11', '2024-06-23 01:27:19', '2024-10-20 10:49:28', '0'),
(20, 'การอนุรักษ์หนังใหญ่วัดสว่างอารมณ์ : กรณีศึกษาหนังใหญ่วัดสว่างอารมณ์ ตำบลต้นโพธิ์ อำเภอเมืองสิงห์บุรี จังหวัดสิงห์บุรี', 'วนิดา เพิ่มศิริ , ธนิดา ภู่แดง, ศรีสุภา นาคธน, สุชาติ อ่อนสันทัด, ณัฐธวัลรัตน์ ดอกไม้งาม', 'งานวิจัย', 'หนังใหญ่ , การอนุรักษ์', '2567', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'การอนุรักษ์หนังใหญ่วัดสว่างอารมณ์ มีวัตถุประสงค์ 1) เพื่อศึกษาขั้นตอนการสร้างหนังใหญ่\r\nวัดสว่างอารมณ์ จังหวัดสิงห์บุรีในอดีตและปัจจุบัน และ2) สืบสานการอนุรักษ์และการสานต่อของชุมชน ภายหลังการศึกษาเสร็จสิ้นแล้วพบว่า\r\n    ๑. หนังใหญ่วัดสว่างอารมณ์ จังหวัดสิงห์บุรีในอดีตและปัจจุบัน มีดังนี้\r\n	๑.๑  การแสดงหนังใหญ่วัดสว่างอารมณ์ มีองค์ประกอบที่สำคัญซึ่งมีรายละเอียด ได้แก่\r\n 		1.๑.๑  ตัวหนัง ทำจากแผ่นหนังวัวแห้งขนาดใหญ่แกะสลักฉลุลวดลายสวยงามเป็นตัวละครต่างๆ ตรึงแผ่นหนังด้วยก้านไม้ เคลื่อนไหวโดยการเชิดผ่านแสงทาบเงาลงบนจอ\r\n                 	๑.๑.2  จอหนังเป็นผ้าขาวผืนใหญ่ สำหรับให้ตัวหนังทาบขึงจอในแนวสูงและกว้างรอบจอใช้ผ้าสีแดงทาบริมทั้งสี่ด้านเพื่อคนดูจะได้มองเห็น\r\n                 	1.๑.3  ดนตรีประกอบการแสดงใช้วงปี่พาทย์เครื่องใหญ่บรรเลงเพลงประกอบการเคลื่อนไหวและแสดงอารมณ์ต่างๆ ของการแสดง\r\n                 	1.1.4  ผู้เชิด เป็นชาย ผู้เชิดหนังต้องเป็นผู้ที่มีพื้นฐานความรู้ ความชำนาญในการเต้นโขนมีหน้าที่บังคับตัวหนังให้เคลื่อนไหวไปอย่างมีชีวิตชีวา เต้น รำไปตามบทบาทและทำนองเพลงคนพากย์ \r\n                	1.๑.5  ผู้พากย์และเจรจา ผู้พากย์จะต้องเข้าใจเรื่องที่จะแสดงเป็นอย่างดีและจะต้องเข้าใจดนตรี เข้าใจเพลงที่ใช้ประกอบการแสดงด้วย การพากย์หนังใหญ่มีลักษณะเดียวกันกับการพากย์โขน ฉะนั้นต้องเตรียมคนพากย์ซึ่งต้องเป็นผู้มีเสียงดี มีความรู้ในเรื่องการอ่านบทกลอน และการพากย์โขน\r\n                  	1.๑.6  ไฟส่องตัวหนัง เพื่อให้เห็นลวดลายที่ตัวหนังชัดเจน\r\n                  	1.๑.7	วรรณกรรมที่ใช้แสดง นิยมแสดงเรื่องรามเกียรติ์\r\n 	1.๒. ขั้นตอนและวิธีการทำหนังใหญ่วัดสว่างอารมณ์\r\n                    	วิธีการทำหนังใหญ่ของวัดสว่างอารมณ์ จังหวัดสิงห์บุรี มีขั้นตอนและวิธีการดังนี้\r\n                    1.๒.1  การเตรียมหนัง ใช้หนังวัวมาทำแต่จะเลือกซื้อจากโรงงาน ทางโรงงาน จะรีดหนังได้ตามขนาดความหนา บาง ตามที่ต้องการปัจจุบันทางวัดซื้อหนังวัวมาจากจังหวัดอ่างทอง\r\n                    1.๒.๒  การฟอกหนัง ปัจจุบันวัดสว่างอารมณ์ เลือกใช้วิธีการซื้อหนังมาจากโรงงานที่ฟอกแล้วนำมาขึงให้หนังตึงแล้วมาขูดขนออกโดยใช้ไม้ที่เตรียมไว้\r\n                    1.๒.3  การเขียนลาย ใช้วิธีการลอกลายหรือร่างลายโดยใช้กระดาษไขวางทับแบบแล้วร่างลวดลายจากต้นแบบหรือการวาดลวดลายแล้วนำไปถ่ายเป็นพิมพ์เขียว  หรือถ่ายเอกสารขนาด A3 หรือ A4 แล้วนำมาขยายตามสัดส่วนของตัวหนัง จากนั้นปะลงบนตัวหนังแล้วจึงทำการฉลุลาย\r\n                    1.๒.4  การปรุลาย จะใช้ตัวตุ๊ดตู่หรือตาไก่เป็นตัวตอกตามลวดลายเช่นเดียวกับสมัยโบราณเครื่องมือที่ใช้จะมีทั้งเครื่องมือตอกและ เครื่องมือตัด มีดเป็นมีดปลายแหลม ใช้ตัดหรือ\r\n เฉือนและกรรไกรที่ต้องการตัดออกให้เป็นช่อง\r\n         		1.๒.5  การลงสี สีจะใช้สีที่มีในสมัยโบราณ คือ ยังคงใช้สีดำ ขาว น้ำตาลแดง เขียว ปัจจุบันมีสีที่ใช้ทาตัวหนังที่ทำให้การทำงานสะดวกขึ้นคือ สีแอลกอฮอล์ย้อมหนัง ซึ่งมีหลายสีให้เลือก คุณสมบัติของสีแอลกอฮอล์ทำให้สีติดซึมลงไปในเนื้อหนัง การลงสีจะมีการระบายสองทางคือทั้งด้านหน้าและด้านหลัง จุดที่เป็นสีขาวจะไม่ลงสีใช้เป็นผิวเดิมของหนัง\r\n		 1.๒.6  การเคลือบหนังจะใช้น้ำยาเคลือบตัวหนังหลังจากลงสีเรียบร้อยแล้วสามารถกันความชื้นและรักษาสภาพของหนังและสีให้คงทน\r\n          		1.๒.7  การผูกไม้ การผูกไม้หรือเรียกว่าไม้ตับหนังจะใช้ไม้ไผ่ที่แก่จัดมาเหลาเป็นด้ามไว้จับเวลาเชิดหนัง ไม้ตับหนังทำมาจากไผ่ จึงต้องนำไม้ไปรมควันไฟเพื่อกันพวกแมลงหรือมอดที่จะมากินไม้ไผ่\r\n	2.  การสืบสาน การอนุรักษ์ และการสานต่อของชุมชน\r\n 	 หนังใหญ่วัดสว่างอารมณ์จังหวัดสิงห์บุรีมีวิธีการ การอนุรักษ์และการเผยแพร่ ดังนี้\r\n 	๒.๑  ปรับปรุงพัฒนาพิพิธภัณฑ์ ให้เป็นแหล่งเรียนรู้สำหรับนักเรียน นักศึกษาและประชาชนทั่วไป\r\n          	๒.2  อนุรักษ์หนังใหญ่ โดยดูแลรักษา ซ่อมแซมตัวหนังที่ชำรุด สร้างตัวหนังใหม่แทนตัวที่ชำรุด\r\n          	๒.3  เชิญชวนและประสานงานกับนักเรียนและบุตรหลานของชุมชนวัดสว่างอารมณ์ มาฝึกเชิดหนังใหญ่และการแกะสลักตัวหนัง\r\n          	๒.4  จัดพิธีครอบครู ไหว้ครูหนังใหญ่เป็นประจำทุกปี ในปัจจุบันกำหนดการจัดงาน\r\nในเดือน ๙ หรือประมาณเดือนสิงหาคม ในการนี้จะมีการแสดงหนังใหญ่ด้วย\r\n          	๒.5  จัดทำหลักสูตรท้องถิ่นหนังใหญ่เพื่อเป็นหลักสูตรในการจัดการเรียนการสอนสำหรับนักเรียนชั้นประถมศึกษาในจังหวัดสิงห์บุรี เช่น โรงเรียนเทศบาล ๓ พรหมรวมมิตร และโรงเรียนวัดพรหมสาคร \r\n          	๒.6  เผยแพร่ประชาสัมพันธ์ ให้ชุมชน องค์กร หน่วยงานต่างๆมาชมการแสดงหนังใหญ่ \r\nและพิพิธภัณฑ์หนังใหญ่ โดยทำแผ่นพับประชาสัมพันธ์  ป้ายประชาสัมพันธ์ ทำสื่อออนไลน์ เป็นต้น\r\n         	๒.7 นำเศษหนังที่เหลือจากการแกะสลักตัวหนังมาทำเป็นของที่ระลึกเพื่อจัดจำหน่าย \r\nเช่น พวงกุญแจ ทำตัวหนังขนาดย่อส่วนและนำมาใส่กรอบเป็นของที่ระลึก', 'research-1802639905010035.text', '2024-06-23', NULL, '1802639905010501.jpg', NULL, '1802639905010058.pdf', 27, 'การอนุรักษ์หนังใหญ่วัดสว่างอารมณ์ : กรณีศึกษาหนังใหญ่วัดสว่างอารมณ์ ตำบลต้นโพธิ์ อำเภอเมืองสิงห์บุรี จังหวัดสิงห์บุรี', 'การอนุรักษ์หนังใหญ่วัดสว่างอารมณ์ : กรณีศึกษาหนังใหญ่วัดสว่างอารมณ์ ตำบลต้นโพธิ์ อำเภอเมืองสิงห์บุรี จังหวัดสิงห์บุรี', 'การอนุรักษ์หนังใหญ่วัดสว่างอารมณ์ : กรณีศึกษาหนังใหญ่วัดสว่างอารมณ์ ตำบลต้นโพธิ์ อำเภอเมืองสิงห์บุรี จังหวัดสิงห์บุรี', '172.16.108.11', '2024-06-23 01:29:39', '2024-10-24 03:17:49', '0'),
(21, 'การศึกษาแหล่งเรียนรู้ประเภทพิพิธภัณฑ์ในจังหวัดลพบุรี', 'ผศ.วิไลวรรณ ฉ่ำพิรุณ', 'งานวิจัย', 'แหล่งเรียนรู้ชุมชน พิพิธภัณฑ์', '2567', 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'การศึกษาวิจัย เรื่อง การศึกษาแหล่งเรียนรู้ประเภทพิพิธภัณฑ์ในจังหวัดลพบุรีครั้งนี้ มีวัตถุประสงค์ เพื่อศึกษาสภาพของแหล่งเรียนรู้ประเภทพิพิธภัณฑ์ในจังหวัดลพบุรี จำนวน 20 แหล่ง โดยศึกษาในประเด็น สถานที่ตั้ง การดำเนินงาน เนื้อหาการจัดแสดง กาให้รบริการ  ความร่วมมือกับหน่วยงานอื่น สภาพสิ่งแวดล้อมที่เอื้อต่อการเรียนรู้และปัญหาอุปสรรค  เพื่อส่งเสริมการเรียนรู้ตลอดชีวิตของเยาวชนและประชาชนและเพื่อนำข้อมูลไปจัดทำทะเบียนแหล่งเรียนรู้ในจังหวัดลพบุรี วิธีการศึกษาใช้รูปแบบวิจัยเชิงคุณภาพและเชิงปริมาณ โดยใช้แบบสอบถามและแบบสัมภาษณ์เป็นเครื่องมือในการเก็บรวบรวมข้อมูล มีการสุ่มตัวอย่างแบบเฉพาะเจาะจง จำนวน 30 คน ที่เป็นผู้ก่อตั้ง ผู้บริหาร คณะกรรมการ  ผู้ดำเนินงานและผู้เกี่ยวข้องกับแหล่งเรียนรู้ประเภทพิพิธภัณฑ์ในจังหวัดลพบุรีจำนวน 20 แห่ง และทำการวิเคราะห์ข้อมูล นําเสนอผลการศึกษาแบบพรรณนาวิเคราะห์ (Descriptive Analysis)\r\n		ผลการศึกษาวิจัยพบว่า แหล่งเรียนรู้ประเภทพิพิธภัณฑ์ในจังหวัดลพบุรีทั้ง 20 แห่ง ตั้งอยู่ในสถานที่หลากหลายแตกต่างกัน แบ่งตามสถานที่ตั้งและการดำเนินงานได้เป็น 6 กลุ่ม คือ 1.กลุ่มที่ตั้งอยู่ภายในบริเวณวัด ก่อตั้งและดำเนินงานโดยวัด จำนวน 4 แห่ง ได้แก่  พิพิธภัณฑ์วัดโคกหม้อ พิพิธภัณฑ์พระครูสนิทวินัยการวัดท่าโขลง   พิพิธภัณฑ์วัดถ้ำตะโกพุทธโสภา  พิพิธภัณฑ์วัดเขาวงพระจันทร์    2. กลุ่มที่ตั้งอยู่ภายในบริเวณวัด ก่อตั้งและดำเนินงานโดยวัดและชุมชน จำนวน 8 แห่ง ได้แก่ พิพิธภัณฑ์หอโสภณศิลป์ พิพิธภัณฑ์พื้นบ้านไทยพวนโคกกระเทียม  พิพิธภัณฑ์เรือพื้นบ้านวัดยาง ณ รังสี พิพิธภัณฑ์วัดไลย์  พิพิธภัณฑ์ชุมชนหัวสำโรง  พิพิธภัณฑ์พื้นบ้านไทยพวนวัดบ้านทราย  พิพิธภัณฑ์พื้นบ้านไทยพวนบ้านหลุมข้าว  พิพิธภัณฑ์บ้านพรหมทินใต้ ปิดให้บริการ 2 แห่ง ได้แก่ พิพิธภัณฑ์วัดถ้ำตะโกพุทธโสภาและ พิพิธภัณฑ์ชุมชนหัวสำโรง เนื่องจากขาดบุคลากร\r\nเฝ้าพิพิธภัณฑ์ 3. กลุ่มที่ตั้งอยู่ในสถานที่ราชการและดำเนินงานโดยหน่วยราชการ 2 แห่งได้แก่  พิพิธภัณฑ์แห่งชาติสมเด็จพระนารายณ์มหาราช และพิพิธภัณฑ์ลุ่มน้ำป่าสัก 4. กลุ่มที่ตั้งอยู่ในเขตทหารและ\r\n\r\n\r\n\r\n												       ข\r\n\r\nดำเนินงานโดยทหารจำนวน 4 แห่ง ได้แก่  พิพิธภัณฑ์ทหารรบพิเศษ  พิพิธภัณฑ์ศูนย์การทหารปืนใหญ่  พิพิธภัณฑ์การบินทหารบก  พิพิธภัณฑ์โรงพยาบาลอานันทมหิดล 5. พิพิธภัณฑ์ที่ตั้งอยู่ในชุมชนและดำเนินงานโดยชุมชน ได้แก่ พิพิธภัณฑ์ไทยเบิ้งโคกสลุง 6. พิพิธภัณฑ์ที่ตั้งอยู่ในองค์การบริหารส่วนตำบลซับจำปาภายใต้การดำเนินงานขององค์การบริหารส่วนตำบลซับจำปา \r\n              	สภาพภายนอกโดยรวมของพิพิธภัณฑ์ทั้ง 20 แห่ง ขึ้นอยู่กับสถานที่ตั้ง โดยรวมอยู่ใสภาพดี ต้องการการปรับปรุงภูมิทัศน์ ชื่อพิพิธภัณฑ์และป้ายบอกทาง ยกเว้นอาคารหลังแรกของพิพิธภัณฑ์เรือวัดยาง \r\nณ รังสี อยู่ในสภาพทรุดโทรม\r\n             	ด้านการดำเนินงาน พิพิธภัณฑ์ที่ตั้งในวัด ดำเนินงานกันเอง ไม่มีรูปแบบคณะกรรมการ ไม่ได้รับการสนับสนุนงบประมาณจากภาครัฐอย่างต่อเนื่อง ส่วนพิพิธภัณฑ์ที่ตั้งในสถานที่ราชการ ดำเนินงานโดย\r\nหน่วยราชการต้องการงบประมาณในการดำเนินงานเช่นกัน \r\n             	ด้านการจัดแสดง พิพิธภัณฑ์ที่ตั้งในบริเวณวัด จัดแสดงกันเองตามวัตถุที่มี ยังไม่เป็นหมวดหมู่ ยกเว้น พิพิธภัณฑ์บ้านพรหมทินใต้ที่มีการจัดแสดงที่เป็นหมวดหมู่ ทันสมัย ได้รับการสนับสนุนในการสร้างอาคารและการจัดแสดงจาก มูลนิธิกรุงเทพประกันภัย จำกัด พิพิธภัณฑ์ที่ตั้งอยู่ในสถานที่ราชการ มีการจัดแสดงที่เป็นหมวดหมู่ \r\n  	ด้านการบริการ พิพิธภัณฑ์ที่ตั้งอยู่ในบริเวณวัดทั้ง 12 แห่ง จะให้บริการเฉพาะการนัดหมายล่วงหน้าเท่านั้น เพราะโดยปกติ พิพิธภัณฑ์จะปิด เพราะไม่มีบุคลากรประจำพิพิธภัณฑ์ ไม่มีค่าใช้จ่ายในการเยี่ยมชม พิพิธภัณฑ์ที่ตั้งอยู่ในเขตทหาร เยี่ยมชมได้ในวัน เวลาราชการและต้องนัดหมายล่วงหน้าเช่นกัน มีค่าใช้จ่ายในการเยี่ยมชม พิพิธภัณฑ์ไทยเบิ้งโคกสลุง เยี่ยมชมได้ทุกวัน ไม่เสียค่าใช้จ่าย แต่ถ้าต้องการให้มีการจัดกิจกรรม ต้องแจ้งล่วงหน้าและอาจมีค่าใช้จ่ายบ้าง \r\n	  	ด้านสภาพแวดล้อมที่เอื้อต่อการเรียนรู้ นอกจากองค์ความรู้ในพิพิธภัณฑ์ทั้ง 20 แห่งแล้ว \r\nยังมีสิ่งแวดล้อมพิพิธภัณฑ์ต่างๆที่เป็นประโยชน์ต่อการเรียนรู้และเป็นที่รู้จักกันทั่วไป ได้แก่ พระนารายณ์ราชนิเวศน์ เขื่อนป่าสักชลสิทธิ์ แหล่งโบราณคดีบ้านพรหมทินใต้ ป่าจำปีสิรินธร ชุมชนตำบลโคกสลุง เป็นต้น\r\n   	 	ด้านปัญหา อุปสรรค พิพิธภัณฑ์ที่ตั้งในบริเวณวัด ดำเนินงานโดยวัดและชุมชน มีปัญหาในทุกๆ ด้าน โดยเฉพาะด้านการดำเนินงานของพิพิธภัณฑ์ เพราะไม่มีบุคลากรประจำพิพิธภัณฑ์ ขาดงบประมาณในการดำเนินงาน ต้องการนักวิชาการในการพัฒนาการจัดแสดงและบุคลากรในการนำชม มีการร่วมมือกับหน่วยงานอื่นน้อยมาก   \r\n		ข้อเสนอแนะ หน่วยงานที่เกี่ยวข้องต้องบูรณาการกับองค์กรต่างๆในการพัฒนาแหล่งเรียนรู้ประเภทพิพิธภัณฑ์ให้ได้มาตรฐานและส่งเสริมการเรียนรู้ตลอดชีวิตโดยผ่านการเยี่ยมชมพิพิธภัณฑ์', 'research-1808059494077591.text', '2024-08-22', NULL, '1808059494092459.jpg', NULL, '1808059494077617.pdf', 13, 'การศึกษาแหล่งเรียนรู้ประเภทพิพิธภัณฑ์ในจังหวัดลพบุรี', 'การศึกษาแหล่งเรียนรู้ประเภทพิพิธภัณฑ์ในจังหวัดลพบุรี', 'การศึกษาแหล่งเรียนรู้ประเภทพิพิธภัณฑ์ในจังหวัดลพบุรี', '172.16.108.11', '2024-08-21 21:11:42', '2024-10-26 03:39:17', '0');
INSERT INTO `slideshows` (`id`, `title`, `description`, `link`, `image_desktop`, `ip_address`, `created_at`, `updated_at`, `deleted_at`) VALUES
(2, 'สำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'สำนักศิลปะและวัฒนธรรม เป็นหน่วยงานสนับสนุนการผลิตบัณฑิต โดยจัดกิจกรรมทำนุบำรุงศิลปวัฒนธรรมให้แก่นักเรียน นักศึกษา บุคลากรของมหาวิทยาลัยฯ และบุคคลทั่วไป อย่างต่อเนื่อง โดยมี การแบ่งการบริหารงานให้สอดคล้องกับภารกิจเป็น 4 งาน ได้แก่ งานธุรการ งานหอวัฒนธรรม งานส่งเสริมและเผยแพร่ และงานศึกษาค้นคว้าวิจัย', 'https://culture.tru:8890/', '1759980199774586.jpg', '::1', '2023-03-10 04:31:53', NULL, '0');
INSERT INTO `studies` (`id`, `title`, `intro`, `file_text`, `date`, `slug`, `image_desktop`, `status`, `file_pdf`, `count_view`, `meta_title`, `meta_description`, `meta_keyword`, `ip_address`, `created_at`, `updated_at`, `deleted_at`) VALUES
(2, 'ขอเชิญผู้ที่สนใจชมนิทรรศการสมเด็จพระนารายณ์ศึกษา เนื่องในโอกาสครบรอบ 334 ปี วันสวรรคตสมเด็จพระนารายณ์มหาราช', 'ขอเชิญชมนิทรรศการสมเด็จพระนารายณ์ศึกษา เนื่องในโอกาสครบรอบ 334 ปี วันสวรรคตสมเด็จพระนารายณ์มหาราช ฟรีไม่มีค่าใช้จ่าย ณ อาคารสำนักศิลปะและวัฒนธรรม มหาวิทยาลัยราชภัฏเทพสตรี', 'studys-1779356626284583.text', '2023-11-09', NULL, '1779356626293394.jpg', NULL, '1779356626287764.pdf', 68, 'นิทรรศการสมเด็จพระนารายณ์ศึกษา เนื่องในโอกาสครบรอบ 334 ปี วันสวรรคตสมเด็จพระนารายณ์มหาราช', 'นิทรรศการสมเด็จพระนารายณ์ศึกษา เนื่องในโอกาสครบรอบ 334 ปี วันสวรรคตสมเด็จพระนารายณ์มหาราช', 'นิทรรศการสมเด็จพระนารายณ์ศึกษา เนื่องในโอกาสครบรอบ 334 ปี วันสวรรคตสมเด็จพระนารายณ์มหาราช', '10.50.31.233', '2023-10-10 01:31:54', '2024-10-24 10:17:59', '0');
